export const LECCIONES = [
  {"slug":"que-significa-tokenizar-un-activo","modulo":1,"titulo":"Tokenizar no es «meter tu activo en blockchain»: qué significa de verdad","nivel":"principiante","categoria":"Fundamentos","minutos":10,"resumen":"El token no es tu activo. Es la anotación digital de un derecho sobre ese activo. Tu edificio sigue siendo tu edificio, con su escritura, sus cargas y sus impuestos.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"evaluador-viabilidad","url":"https://rwadar.pages.dev/academy/que-significa-tokenizar-un-activo","tldr":[[{"v":"El token no es tu activo.","b":1},{"v":" Es la anotación digital de un derecho sobre ese activo. Tu edificio sigue siendo tu edificio, con su escritura, sus cargas y sus impuestos."}],[{"v":"La tokenización cambia tres cosas:","b":1},{"v":" cómo se divide el derecho, dónde queda registrado quién lo tiene y a quién puedes ofrecérselo. Nada más — y nada menos."}],[{"v":"No cambia otras cuatro:","b":1},{"v":" no crea valor, no garantiza compradores, no te libra de la ley y no elimina el riesgo de quien está al otro lado."}]],"preambulo":[],"cuerpo":[{"t":"h3","texto":[{"v":"La confusión con la que empieza casi todo el mundo"}]},{"t":"p","texto":[{"v":"Cuando alguien oye por primera vez «tokenizar un inmueble», lo normal es imaginar que el edificio, de algún modo, "},{"v":"entra","i":1},{"v":" en una tecnología. Que se convierte en otra cosa. Que pasa a vivir en un sitio nuevo."}]},{"t":"p","texto":[{"v":"No ocurre nada de eso."}]},{"t":"p","texto":[{"v":"El edificio se queda exactamente donde está. Sigue teniendo una escritura, un Registro de la Propiedad, un IBI que pagar y unos inquilinos que llaman cuando se rompe la caldera. Lo que se tokeniza no es el ladrillo: es "},{"v":"el derecho","b":1},{"v":" que alguien tiene sobre ese ladrillo."}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"Un token de activo real es la representación digital de un derecho —de propiedad, de crédito, de participación— sobre un bien que existe fuera del sistema digital. El token es el título; el activo sigue siendo el activo."}]}]},{"t":"p","texto":[{"v":"Esta distinción no es un matiz académico. Es lo que separa un proyecto que funciona de uno que se cae a los seis meses, porque casi todos los problemas de una tokenización nacen en el mundo físico y legal, no en el tecnológico."}]},{"t":"h3","texto":[{"v":"Qué es exactamente un token de activo real"}]},{"t":"p","texto":[{"v":"Piensa en cómo funcionan hoy las acciones de una empresa cotizada. Tú no guardas un papel en un cajón: existe una "},{"v":"anotación en cuenta","b":1},{"v":" en un registro electrónico que dice que cierto número de acciones son tuyas. Ese registro tiene un responsable, unas normas y un supervisor."}]},{"t":"p","texto":[{"v":"Un token de activo real hace lo mismo, con una diferencia: la anotación no vive en el sistema tradicional de un depositario central, sino en un "},{"v":"registro distribuido","b":1},{"v":" —una base de datos replicada y verificable— donde cada movimiento queda trazado."}]},{"t":"p","texto":[{"v":"Es decir: cambia la "},{"v":"tecnología del registro","i":1},{"v":", no la "},{"v":"naturaleza del derecho","i":1},{"v":". Si lo que representas es una participación en una sociedad que posee un inmueble, sigues teniendo una participación societaria, con todo lo que eso implica legalmente. El envoltorio es nuevo; el contenido, no."}]},{"t":"h3","texto":[{"v":"Las tres cosas que la tokenización sí cambia"}]},{"t":"p","texto":[{"v":"1. El fraccionamiento se vuelve barato.","b":1},{"br":1},{"v":"Dividir la propiedad de un activo siempre fue posible —una sociedad con muchos socios, un fondo, una copropiedad—, pero cada división costaba notaría, papeleo y tiempo. Con un registro digital, dividir un derecho en mil partes tiene prácticamente el mismo coste operativo que dividirlo en diez. Eso abre la puerta a tickets de entrada mucho más pequeños."}]},{"t":"p","texto":[{"v":"2. La trazabilidad pasa a ser automática.","b":1},{"br":1},{"v":"Quién tuvo qué, cuándo y a quién se lo transfirió queda registrado de forma verificable y difícil de alterar. Para un activo que va a tener decenas o cientos de titulares, eso reduce mucho el coste de administrar el registro."}]},{"t":"p","texto":[{"v":"3. La distribución deja de tener fronteras técnicas.","b":1},{"br":1},{"v":"Ofrecer una participación a inversores de otro país deja de ser un problema "},{"v":"técnico","i":1},{"v":". Ojo con esta frase: deja de ser un problema técnico, pero "},{"v":"sigue siendo un problema legal","b":1},{"v":", y de los gordos. Cada jurisdicción decide a quién puedes ofrecer qué."}]},{"t":"h3","texto":[{"v":"Las cuatro cosas que la tokenización NO cambia"}]},{"t":"p","texto":[{"v":"Aquí es donde conviene frenar, porque es donde el sector ha generado más expectativas de las que puede cumplir."}]},{"t":"recuadro","tipo":"aviso","titulo":"Atención — lo que ningún proveedor debería prometerte","bloques":[{"t":"p","texto":[{"v":"No crea valor.","b":1},{"v":" Si tu local comercial vale ochocientos mil euros, tokenizarlo no lo convierte en un activo de un millón. Fraccionar un valor no lo aumenta: solo lo reparte."}]},{"t":"p","texto":[{"v":"No garantiza liquidez.","b":1},{"v":" Que un derecho sea divisible y transferible no significa que exista alguien dispuesto a comprarlo. La liquidez la crean los compradores, no la tecnología. Esta es, con diferencia, la promesa más incumplida del sector."}]},{"t":"p","texto":[{"v":"No te saca del marco legal.","b":1},{"v":" Si lo que emites es jurídicamente un valor negociable, te aplica la normativa de valores, con su registro, sus obligaciones de información y su supervisor. La tecnología no es una jurisdicción alternativa."}]},{"t":"p","texto":[{"v":"No elimina el riesgo de contraparte.","b":1},{"v":" Sigues dependiendo de que la plataforma exista mañana, de que quien custodia el registro haga bien su trabajo y de que el activo subyacente rinda lo que se espera de él."}]}]},{"t":"h3","texto":[{"v":"Un ejemplo concreto, con los pies en el suelo"}]},{"t":"p","texto":[{"v":"Supongamos un edificio de oficinas valorado en dos millones de euros, propiedad de una sociedad. El propietario quiere dar entrada a inversores sin vender el edificio entero ni endeudarse más."}]},{"t":"p","texto":[{"v":"Sin tokenizar:","b":1},{"v":" busca dos o tres socios con capacidad para poner varios cientos de miles de euros cada uno, negocia un pacto de socios, va al notario y modifica la estructura societaria. Meses de trabajo y un universo de compradores muy reducido."}]},{"t":"p","texto":[{"v":"Tokenizando:","b":1},{"v":" las participaciones de esa sociedad se representan mediante registro distribuido y se dividen en unidades pequeñas. El universo potencial de inversores se amplía muchísimo, y el registro de quién tiene qué se administra solo."}]},{"t":"p","texto":[{"v":"Lo que no cambia en ninguno de los dos escenarios:","b":1},{"v":" el edificio sigue valiendo lo que vale, hay que hacer una valoración independiente creíble, hay que limpiar las cargas si las hay, hay que cumplir la normativa aplicable a la oferta de participaciones, y sigue haciendo falta que alguien quiera comprar."}]},{"t":"p","texto":[{"v":"Cifras ilustrativas, elegidas solo para explicar el mecanismo. No representan ningún caso real ni ninguna estimación de coste o resultado.","i":1}]},{"t":"h3","texto":[{"v":"Entonces, ¿para qué sirve realmente?"}]},{"t":"p","texto":[{"v":"La tokenización aporta valor cuando se cumple al menos una de estas tres condiciones:"}]},{"t":"ul","items":[[{"v":"Tu activo es indivisible y caro","b":1},{"v":", y esa indivisibilidad te está cerrando el acceso a inversores que sí entrarían con un ticket menor."}],[{"v":"Tienes muchos titulares o los vas a tener","b":1},{"v":", y administrar ese registro por medios tradicionales te resulta caro y lento."}],[{"v":"Tu base de inversores potencial está dispersa geográficamente","b":1},{"v":", y el canal tradicional no llega a ella."}]]},{"t":"p","texto":[{"v":"Si tu caso no encaja en ninguna de las tres, es perfectamente razonable que la respuesta correcta sea "},{"v":"no tokenizar","b":1},{"v":". Lo diremos varias veces a lo largo de esta Academy: no todo activo debe tokenizarse, y reconocerlo a tiempo te ahorra mucho dinero."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"En la "},{"v":"Lección 2","b":1},{"v":" verás quién interviene en una tokenización: seis roles distintos, con licencias y responsabilidades distintas. Es el mapa que necesitas para entender por qué ningún proveedor puede hacerlo todo solo — y para desconfiar razonablemente del que diga que sí."}]}],"glosario":[{"termino":"Token de activo real (RWA)","definicion":[{"v":"Representación digital de un derecho sobre un bien que existe en el mundo físico o financiero: un inmueble, un préstamo, una participación en una empresa, una obra de arte. El token registra quién posee el derecho; no sustituye al bien."}]},{"termino":"Registro distribuido (DLT)","definicion":[{"v":"Base de datos replicada entre varios participantes que verifican y conservan las anotaciones de forma conjunta. Su utilidad aquí es que hace las inscripciones trazables y difíciles de alterar sin dejar rastro. «Blockchain» es el tipo más conocido de registro distribuido."}]},{"termino":"Entidad responsable de la inscripción y el registro (ERIR)","definicion":[{"v":"Figura prevista en la normativa española del mercado de valores para las emisiones representadas mediante registro distribuido. Es la entidad autorizada que administra el registro y responde de que las inscripciones reflejen la realidad jurídica de la titularidad. No cualquier empresa tecnológica puede serlo."}]}],"quiz":[{"enunciado":[{"v":"Una empresa te ofrece «tokenizar tu nave industrial para que gane liquidez inmediata». ¿Qué es lo primero que deberías cuestionar?"}],"opciones":[[{"v":"Que la nave sea apta para representarse digitalmente"}],[{"v":"Que la liquidez dependa de la tecnología y no de que existan compradores"}],[{"v":"Que el token vaya a valer más que la nave"}],[{"v":"Que la nave tenga que cambiar de ubicación"}]],"correcta":1,"explicacion":[{"t":"p","texto":[{"v":"Fraccionar un derecho lo hace "},{"v":"divisible","i":1},{"v":", no "},{"v":"líquido","i":1},{"v":". La liquidez la produce la existencia de compradores reales y de un mercado donde encontrarse, no el hecho de dividir el activo en unidades pequeñas. Cuando un proveedor promete liquidez «inmediata» sin explicar de dónde vendrán esos compradores, la promesa está vacía. Lo veremos a fondo en la Lección 6."}]}]},{"enunciado":[{"v":"¿Cuál de estas afirmaciones describe correctamente la relación entre el token y el activo?"}],"opciones":[[{"v":"El token sustituye al activo, que deja de existir jurídicamente"}],[{"v":"El token es una copia digital del activo"}],[{"v":"El token representa un derecho sobre el activo, que sigue existiendo con su régimen legal propio"}],[{"v":"El token y el activo son la misma cosa expresada en dos formatos"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"El activo permanece intacto: mismo bien, misma escritura o contrato, mismas obligaciones fiscales y registrales. Lo que se digitaliza es la anotación de quién ostenta un derecho sobre él. Confundir ambos planos es el error de partida más frecuente, y el que lleva a subestimar el trabajo legal y documental que hay detrás de cualquier emisión."}]}]},{"enunciado":[{"v":"Un promotor te dice: «al tokenizar, la operación pasa a regirse por la tecnología y no por la normativa de valores». ¿Cómo deberías interpretarlo?"}],"opciones":[[{"v":"Es correcto si el registro distribuido es público"}],[{"v":"Es correcto solo para activos inmobiliarios"}],[{"v":"Es una señal de alarma: la tecnología empleada no altera la calificación jurídica de lo que se emite"}],[{"v":"Es correcto si la emisión se dirige únicamente a inversores profesionales"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"La calificación de lo que emites depende de qué derecho representa, no de con qué tecnología lo registras. Si lo emitido es jurídicamente un valor negociable, le aplica la normativa de valores independientemente de que se anote en un registro distribuido. Cualquier interlocutor que presente la tecnología como una vía para esquivar el marco regulatorio te está describiendo un riesgo, no una ventaja."}]}]}],"siguientePaso":{"titulo":"¿Tu activo está preparado?","bloques":[{"t":"p","texto":[{"v":"Antes de hablar con ningún proveedor, comprueba en qué punto estás. El "},{"v":"Evaluador de Viabilidad de RWAdar","b":1},{"v":" te devuelve una puntuación de madurez y el mapa de lo que te falta —documentación, estructura, valoración— en unos minutos."}]},{"t":"p","texto":[{"v":"Puedes completarlo de forma anónima:","b":1},{"v":" no necesitas identificar tu activo ni facilitar datos personales para ver el resultado. Si más adelante decides contactar con un proveedor, se te pedirá un consentimiento específico para ese proveedor concreto, y podrás revocarlo cuando quieras."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]},{"t":"p","texto":[{"v":"¿Prefieres explorar primero? "},{"a":"radar","v":"Abrir el radar"},{"v":" y filtra las plataformas verificadas por región, tipo de activo y nivel de acceso. También publicamos las que "},{"v":"no","b":1},{"v":" superan nuestros criterios, con el motivo y la fuente."}]}]},"notaLegal":[]},
  {"slug":"quien-es-quien-actores-tokenizacion","modulo":2,"titulo":"Quién es quién: el mapa de actores de una tokenización","nivel":"principiante","categoria":"Fundamentos","minutos":14,"resumen":"Una tokenización no la hace una empresa: la hacen seis. Cada rol tiene una función distinta, una responsabilidad distinta y, en varios casos, una licencia distinta.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"radar-categorias","url":"https://rwadar.pages.dev/academy/quien-es-quien-actores-tokenizacion","tldr":[[{"v":"Una tokenización no la hace una empresa: la hacen seis.","b":1},{"v":" Cada rol tiene una función distinta, una responsabilidad distinta y, en varios casos, una licencia distinta."}],[{"v":"Ningún proveedor puede cubrirlos todos","b":1},{"v":", y los que dicen que sí suelen estar describiendo una subcontratación que no te enseñan, o una actividad para la que no están autorizados."}],[{"v":"Saber quién responde de qué es tu principal herramienta de protección.","b":1},{"v":" Si algo sale mal, la pregunta no será «¿qué falló?», sino «¿quién respondía de eso?»."}]],"preambulo":[],"cuerpo":[{"t":"h3","texto":[{"v":"El error que cuesta más caro al principio"}]},{"t":"p","texto":[{"v":"La primera reunión comercial de casi cualquier dueño de activo suena parecida: una empresa tecnológica, una presentación bien hecha, y una frase que lo resume todo — "},{"v":"«nosotros nos encargamos de todo, llave en mano»","i":1},{"v":"."}]},{"t":"p","texto":[{"v":"Esa frase es cómoda y es, casi siempre, inexacta. No porque quien la dice mienta necesariamente, sino porque una tokenización es un proceso en el que intervienen funciones que "},{"v":"legalmente no pueden estar en las mismas manos","b":1},{"v":", y otras que sencillamente requieren competencias que ninguna empresa reúne por completo."}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"Tokenizar no es contratar un proveedor. Es coordinar un equipo. Tu trabajo como propietario del activo no es encontrar a alguien que lo haga todo, sino entender qué piezas hacen falta y comprobar que cada una está cubierta por quien debe cubrirla."}]}]},{"t":"p","texto":[{"v":"Esta lección es ese mapa. No es un trámite burocrático: es lo que te permite entrar en una reunión y saber, en diez minutos, si te están contando el proceso completo o solo la parte que ellos venden."}]},{"t":"h3","texto":[{"v":"Los seis roles de una tokenización"}]},{"t":"h4","texto":[{"v":"1. El emisor — tú"}]},{"t":"p","texto":[{"v":"Es quien tiene el activo y quien asume la responsabilidad última frente a los inversores. En la práctica casi nunca eres tú como persona física: se constituye o se utiliza una "},{"v":"sociedad vehículo","b":1},{"v":" que posee el activo, y lo que se emite son derechos sobre esa sociedad o sobre el flujo que genera."}]},{"t":"ul","items":[[{"v":"Qué hace:","b":1},{"v":" aporta el activo, decide la operación, firma y responde."}],[{"v":"Qué no puede delegar:","b":1},{"v":" la responsabilidad. Puedes externalizar la ejecución entera y seguirás siendo el emisor."}],[{"v":"Qué te van a exigir:","b":1},{"v":" titularidad limpia, cargas identificadas, documentación al día e identificación de los socios reales."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Es habitual que los proveedores presenten al emisor como un participante pasivo del proceso. No lo es. Si la emisión se estructura mal, quien tiene el problema encima de la mesa dentro de tres años eres tú, no la empresa que montó la infraestructura."}]}]},{"t":"h4","texto":[{"v":"2. El estructurador legal — el despacho"}]},{"t":"p","texto":[{"v":"Es el rol más determinante y el que más se subestima. Decide "},{"v":"qué se emite exactamente","b":1},{"v":": ¿participaciones de una sociedad? ¿un bono? ¿derechos de crédito? ¿un contrato de cuentas en participación? De esa decisión depende todo lo demás, empezando por si lo emitido es o no un valor negociable, con el régimen legal que eso arrastra."}]},{"t":"ul","items":[[{"v":"Qué hace:","b":1},{"v":" diseña la estructura jurídica, constituye el vehículo si hace falta, redacta el documento de emisión y los contratos, y determina qué obligaciones de información aplican y si existe alguna exención."}],[{"v":"Qué no hace:","b":1},{"v":" no te dice si la operación es una buena idea financiera. Eso no es su función."}],[{"v":"Qué te van a exigir:","b":1},{"v":" decisiones. Un despacho no puede estructurar sin saber a quién quieres dirigirte y en qué países."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Señal de alarma","bloques":[{"t":"p","texto":[{"v":"Si el análisis legal lo aporta «el equipo interno» de la plataforma tecnológica y no un despacho independiente que te emita un dictamen firmado, no tienes cobertura legal: tienes una opinión comercial de quien cobra por que la operación salga adelante."}]}]},{"t":"h4","texto":[{"v":"3. El valorador independiente"}]},{"t":"p","texto":[{"v":"Alguien tiene que decir cuánto vale el activo, y ese alguien no puede ser ni tú ni quien vende la emisión. En inmobiliario suele ser una sociedad de tasación homologada; en una pyme, un experto en valoración de empresas; en arte, un perito con trayectoria contrastable en esa categoría concreta."}]},{"t":"ul","items":[[{"v":"Qué hace:","b":1},{"v":" emite una valoración fundamentada, con metodología explícita y fecha."}],[{"v":"Por qué importa tanto:","b":1},{"v":" es la cifra sobre la que se construye todo el reparto. Si está inflada, la emisión nace con un problema estructural que se manifestará en el momento de vender."}],[{"v":"Qué te van a exigir:","b":1},{"v":" acceso real al activo, documentación y, a veces, malas noticias."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Cuidado con el valorador que propone y paga la propia plataforma. No es necesariamente irregular, pero es un conflicto de interés que debes conocer y valorar. Pregunta siempre quién contrata al valorador y quién le paga."}]}]},{"t":"h4","texto":[{"v":"4. La plataforma tecnológica"}]},{"t":"p","texto":[{"v":"Es el actor más visible del sector y, paradójicamente, el que soporta menos responsabilidad legal sobre el resultado. Construye y opera la infraestructura: los contratos inteligentes, la interfaz por la que los inversores ven su posición, la integración con los procesos de identificación."}]},{"t":"ul","items":[[{"v":"Qué hace:","b":1},{"v":" tecnología. Emisión técnica de los tokens, panel de titulares, automatización de repartos si los hay."}],[{"v":"Qué no hace, aunque a veces lo parezca:","b":1},{"v":" no califica jurídicamente tu emisión, no sustituye al registro autorizado cuando este es obligatorio, y no garantiza que exista un mercado para tus tokens."}],[{"v":"Qué te van a exigir:","b":1},{"v":" especificaciones. Cuántos titulares, qué reglas de transmisión, qué periodicidad de reparto."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Señal de alarma","bloques":[{"t":"p","texto":[{"v":"Una plataforma que responde a preguntas regulatorias con argumentos técnicos —«al estar en blockchain, esto queda fuera de…»— te está describiendo un riesgo, no una ventaja. La tecnología con la que se anota un derecho no cambia la naturaleza jurídica de ese derecho."}]}]},{"t":"h4","texto":[{"v":"5. La entidad de registro y custodia"}]},{"t":"p","texto":[{"v":"Es el rol que más gente desconoce y el que más protege al inversor. Alguien tiene que responder de que el registro diga la verdad: que quien figura como titular de una participación lo sea realmente, y que las transmisiones se reflejen correctamente."}]},{"t":"p","texto":[{"v":"En España, cuando lo emitido son valores negociables representados mediante registro distribuido, esa función corresponde a una "},{"v":"entidad responsable de la inscripción y el registro (ERIR)","b":1},{"v":", que debe estar autorizada para custodiar instrumentos financieros —típicamente entidades de crédito o empresas de servicios de inversión con esa habilitación—. No es un rol que pueda asumir cualquier empresa tecnológica."}]},{"t":"ul","items":[[{"v":"Qué hace:","b":1},{"v":" administra el registro y responde de su integridad y de su correspondencia con la realidad jurídica."}],[{"v":"Por qué importa:","b":1},{"v":" es la diferencia entre un token que representa un derecho oponible y una anotación en la base de datos de una empresa privada."}],[{"v":"Qué debes comprobar:","b":1},{"v":" que la entidad esté efectivamente autorizada y figure en el registro público del supervisor correspondiente."}]]},{"t":"h4","texto":[{"v":"6. El auditor"}]},{"t":"p","texto":[{"v":"Aquí hay que distinguir dos auditorías distintas que a menudo se confunden:"}]},{"t":"ul","items":[[{"v":"Auditoría de cuentas","b":1},{"v":" del vehículo que posee el activo: verifica que la información financiera que reciben los titulares es fiable. Es la que exigirá cualquier inversor institucional."}],[{"v":"Auditoría técnica del contrato inteligente:","b":1},{"v":" revisa que el código haga lo que dice el documento de emisión y que no tenga vulnerabilidades explotables. Es específica del mundo tokenizado y no la cubre un auditor de cuentas."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Que exista «una auditoría» no significa nada por sí solo. Pregunta cuál de las dos, quién la firmó, en qué fecha y si el informe está disponible completo o solo un resumen comercial."}]}]},{"t":"h3","texto":[{"v":"El mapa, de un vistazo"}]},{"t":"tabla","cabecera":[[{"v":"Rol"}],[{"v":"Función principal"}],[{"v":"¿Requiere licencia o habilitación?"}],[{"v":"Si falla, ¿qué ocurre?"}]],"filas":[[[{"v":"Emisor","b":1}],[{"v":"Aporta el activo y responde"}],[{"v":"No, pero asume la responsabilidad"}],[{"v":"Responsabilidad directa frente a titulares"}]],[[{"v":"Estructurador legal","b":1}],[{"v":"Define qué se emite y bajo qué régimen"}],[{"v":"Ejercicio de la abogacía"}],[{"v":"Emisión mal calificada: riesgo regulatorio"}]],[[{"v":"Valorador","b":1}],[{"v":"Determina el valor del activo"}],[{"v":"Homologación según tipo de activo"}],[{"v":"Reparto construido sobre una cifra irreal"}]],[[{"v":"Plataforma tecnológica","b":1}],[{"v":"Infraestructura y contratos inteligentes"}],[{"v":"Depende del servicio prestado"}],[{"v":"Fallo técnico, interrupción, error de código"}]],[[{"v":"Registro y custodia","b":1}],[{"v":"Garantiza la titularidad"}],[{"v":"Sí, autorización supervisada"}],[{"v":"El titular no puede acreditar su derecho"}]],[[{"v":"Auditor","b":1}],[{"v":"Verifica cuentas y/o código"}],[{"v":"Sí, según el tipo de auditoría"}],[{"v":"Información no fiable, vulnerabilidad no detectada"}]]]},{"t":"h3","texto":[{"v":"El séptimo actor del que casi nadie te habla"}]},{"t":"p","texto":[{"v":"Falta uno, y suele aparecer tarde en la conversación: "},{"v":"quien pone la emisión delante de los inversores","b":1},{"v":"."}]},{"t":"p","texto":[{"v":"Captar, comercializar o colocar instrumentos financieros es, en la Unión Europea, una actividad reservada. No la puede hacer libremente cualquiera, ni siquiera el propio emisor sin cumplir determinadas condiciones. Según cómo se estructure la operación y a quién se dirija, intervendrá una empresa de servicios de inversión, una plataforma de financiación participativa autorizada, o se aplicará algún régimen de exención."}]},{"t":"p","texto":[{"v":"Es la parte del proceso donde más proyectos se atascan, porque muchos llegan con la emisión ya construida y descubren entonces que "},{"v":"no tienen forma legal de ofrecérsela a nadie","b":1},{"v":". Lo veremos en detalle en la Lección 4."}]},{"t":"h3","texto":[{"v":"La regla del solapamiento: quién puede acumular roles y quién no"}]},{"t":"p","texto":[{"v":"Es perfectamente normal que un mismo grupo empresarial cubra varias funciones. Lo que no es indiferente es "},{"v":"cuáles","i":1},{"v":"."}]},{"t":"p","texto":[{"v":"Combinaciones habituales y razonables:","b":1},{"v":" plataforma tecnológica + soporte operativo. Estructurador legal + redacción documental. Registro + custodia."}]},{"t":"p","texto":[{"v":"Combinaciones que exigen explicación:","b":1},{"v":" quien estructura y cobra un porcentaje del éxito de la emisión no debería ser quien elige y paga al valorador. Quien opera la tecnología no debería ser quien certifica que esa tecnología es correcta."}]},{"t":"p","texto":[{"v":"Combinaciones que directamente no proceden:","b":1},{"v":" asumir funciones de registro o de colocación sin la autorización correspondiente. Aquí no hay matiz posible ni «modelo alternativo»: o se está autorizado o no se está."}]},{"t":"recuadro","tipo":"idea","titulo":"La pregunta que lo resuelve todo","bloques":[{"t":"p","texto":[{"v":"En cualquier reunión, pregunta: "},{"v":"«¿qué parte de esto hacéis vosotros directamente, qué parte subcontratáis y a quién, y qué autorizaciones tenéis?»","i":1},{"v":". Una respuesta clara y sin incomodidad es la mejor señal de solvencia que vas a obtener gratis. Una respuesta evasiva también te dice todo lo que necesitas saber."}]}]},{"t":"h3","texto":[{"v":"Cinco preguntas para tu primera reunión"}]},{"t":"ol","items":[[{"v":"¿Qué figura jurídica concreta vais a emitir y quién firma ese análisis?"}],[{"v":"¿Quién actuará como entidad de registro y custodia, y dónde puedo verificar su autorización?"}],[{"v":"¿Quién elige y quién paga al valorador independiente?"}],[{"v":"¿Qué auditorías existen, de qué tipo, de qué fecha y puedo leer el informe completo?"}],[{"v":"¿Cómo y a través de quién se va a ofrecer la emisión a inversores?"}]]},{"t":"p","texto":[{"v":"Si una de las cinco no tiene respuesta concreta, no significa que el proveedor sea malo. Significa que esa pieza del mapa todavía no está cubierta — y ahora ya sabes que falta."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"Ya sabes qué es tokenizar y quién interviene. Queda la pregunta que probablemente te trajo aquí: "},{"v":"¿tu activo concreto está en condiciones de entrar en este proceso?","b":1},{"v":" En la "},{"v":"Lección 3","b":1},{"v":" repasamos las cinco condiciones previas —titularidad, cargas, valoración, estructura y tamaño mínimo— y verás por qué muchos proyectos perfectamente razonables no están listos todavía, y qué hace falta para que lo estén."}]}],"glosario":[{"termino":"Sociedad vehículo (SPV)","definicion":[{"v":"Sociedad creada con un fin único: poseer el activo que se va a tokenizar y aislarlo del resto del patrimonio del propietario. Permite que lo que se emite sean derechos sobre una entidad limpia y acotada, en lugar de sobre un patrimonio con obligaciones ajenas al proyecto."}]},{"termino":"Documento de emisión","definicion":[{"v":"Documento que describe formalmente qué se emite, en qué condiciones, con qué derechos y sobre qué activo, incluyendo las características técnicas del registro empleado. Convive con las obligaciones generales de información al inversor —folleto o su exención— cuando resultan aplicables; no las sustituye."}]},{"termino":"Contrato inteligente (smart contract)","definicion":[{"v":"Programa que se ejecuta sobre un registro distribuido y aplica automáticamente reglas previamente definidas: emitir unidades, permitir o bloquear transmisiones, distribuir importes. Ejecuta lo que dice su código, que no siempre coincide con lo que dice el documento legal — de ahí la auditoría técnica."}]}],"quiz":[{"enunciado":[{"v":"Una plataforma te ofrece un servicio «integral»: estructuración legal, tecnología, valoración del activo y custodia del registro, todo con su equipo interno. ¿Cuál es la lectura correcta?"}],"opciones":[[{"v":"Es la opción más eficiente, porque reduce el número de interlocutores"}],[{"v":"Es indiferente: lo relevante es el precio final del paquete"}],[{"v":"Hay funciones que requieren autorización específica y otras que no deberían recaer en quien cobra por el éxito de la emisión; procede pedir detalle de qué se subcontrata y qué autorizaciones existen"}],[{"v":"Es irregular en todos los casos"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Ni todo integral es sospechoso ni todo integral es aceptable. Hay dos filtros distintos: el de "},{"v":"reserva de actividad","b":1},{"v":" —el registro y custodia de valores, o la colocación entre inversores, exigen autorización— y el de "},{"v":"conflicto de interés","b":1},{"v":" —quien estructura y cobra por que la operación salga no debería elegir y pagar al valorador que fija la cifra base—. La respuesta útil no es rechazar el modelo integral, sino pedir el desglose: qué se hace internamente, qué se subcontrata, a quién y con qué habilitación."}]}]},{"enunciado":[{"v":"Tras la emisión se detecta que el registro atribuye a un inversor más participaciones de las que realmente adquirió. ¿Sobre quién recae principalmente la responsabilidad de que el registro refleje la titularidad real?"}],"opciones":[[{"v":"Sobre la plataforma tecnológica que desarrolló el contrato inteligente"}],[{"v":"Sobre la entidad responsable del registro y la custodia"}],[{"v":"Sobre el auditor de cuentas del vehículo"}],[{"v":"Sobre el propio inversor, por no haber revisado su posición"}]],"correcta":1,"explicacion":[{"t":"p","texto":[{"v":"La función de registro no es una tarea técnica más: es la que garantiza que la anotación se corresponde con la realidad jurídica de la titularidad, y por eso se atribuye a una entidad autorizada y supervisada. La plataforma tecnológica puede haber cometido el error material, y responderá de ello en el plano contractual, pero la responsabilidad sobre la integridad del registro es de quien tiene encomendada esa función. Es exactamente la razón por la que conviene verificar la autorización antes de firmar, y no después."}]}]},{"enunciado":[{"v":"¿Qué actor determina si lo que vas a emitir es jurídicamente un valor negociable o no lo es?"}],"opciones":[[{"v":"La plataforma tecnológica, según la infraestructura que utilice"}],[{"v":"El supervisor, que lo comunica antes de cada emisión"}],[{"v":"El análisis jurídico de la estructura, en función del derecho que el token representa"}],[{"v":"El emisor, eligiendo la calificación que prefiera"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"La calificación depende de qué derecho se representa —participación en el capital, derecho de crédito, derecho sobre un flujo—, no de la tecnología empleada ni de la etiqueta que se le ponga en el material comercial. Por eso el estructurador legal es el rol determinante: su análisis decide qué régimen aplica y, en consecuencia, qué obligaciones de registro, información y comercialización arrastra la operación. Ni el emisor puede elegir la calificación que más le convenga, ni el supervisor la comunica de oficio caso por caso."}]}]}],"siguientePaso":{"titulo":"Ahora que conoces los roles, mira el radar con otros ojos","bloques":[{"t":"p","texto":[{"v":"El directorio de RWAdar clasifica a los proveedores "},{"v":"por categoría —marketplace, emisor, infraestructura—","b":1},{"v":" precisamente por lo que acabas de leer: ningún actor cubre todo el mapa, y presentarlos como si fueran intercambiables sería engañarte."}]},{"t":"p","texto":[{"a":"radar-categorias","v":"Abrir el radar y filtrar por categoría"},{"v":" — y consulta también la sección "},{"v":"Fuera del radar","i":1},{"v":", donde publicamos las plataformas que no superan nuestros cuatro criterios de verificación, con el motivo y la fuente."}]},{"t":"p","texto":[{"v":"¿Prefieres empezar por tu propio activo? El "},{"v":"Evaluador de Viabilidad","b":1},{"v":" te dice en qué punto estás y qué te falta. Puedes completarlo de forma anónima: no necesitas identificar tu activo ni facilitar datos personales para ver el resultado."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]}]},"notaLegal":[{"t":"p","texto":[{"v":"La descripción de roles, licencias y responsabilidades contenida en esta lección es una explicación general con fines educativos y no sustituye el análisis de un profesional habilitado sobre tu caso concreto."}]}]},
  {"slug":"es-tu-activo-tokenizable","modulo":3,"titulo":"¿Es tu activo tokenizable? Las cinco condiciones previas","nivel":"principiante","categoria":"Diagnóstico","minutos":15,"resumen":"Casi cualquier activo es tokenizable en teoría. Muy pocos lo son la semana que lo decides. La diferencia está en cinco condiciones previas que se comprueban antes de hablar con nadie.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"evaluador-viabilidad","url":"https://rwadar.pages.dev/academy/es-tu-activo-tokenizable","tldr":[[{"v":"Casi cualquier activo es tokenizable en teoría. Muy pocos lo son la semana que lo decides.","b":1},{"v":" La diferencia está en cinco condiciones previas que se comprueban antes de hablar con nadie."}],[{"v":"Ninguna de las cinco es tecnológica.","b":1},{"v":" Titularidad, cargas, valoración, estructura y tamaño: todas viven en el mundo legal y contable, no en el blockchain."}],[{"v":"Fallar una condición casi nunca significa «no». Significa «todavía no»","b":1},{"v":", y suele venir acompañado de una lista concreta de cosas que se pueden resolver."}]],"preambulo":[],"cuerpo":[{"t":"h3","texto":[{"v":"Por qué esta lección va antes que cualquier reunión"}]},{"t":"p","texto":[{"v":"Un proveedor serio te va a hacer estas preguntas de todos modos. La diferencia entre que te las haga él o que te las hayas hecho tú está en la posición desde la que negocias, en el tiempo que pierdes y en el dinero que gastas antes de descubrir un obstáculo que era visible desde el primer día."}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"La pregunta útil no es «¿se puede tokenizar mi activo?». La respuesta a esa casi siempre es sí. La pregunta útil es "},{"v":"«¿está mi activo en condiciones de ser tokenizado hoy, y si no lo está, qué me falta exactamente?»","b":1},{"v":"."}]}]},{"t":"p","texto":[{"v":"Vamos con las cinco. Al final encontrarás un semáforo para autoevaluarte y una guía de qué hacer si alguna sale en rojo."}]},{"t":"h3","texto":[{"v":"Condición 1 — Titularidad clara y acreditable"}]},{"t":"p","texto":[{"v":"La pregunta que la resume:","b":1},{"v":" "},{"v":"¿podrías vender el activo entero mañana sin pedir permiso a nadie que no esté plenamente identificado y localizado?","i":1}]},{"t":"p","texto":[{"v":"Si la respuesta no es un sí rotundo, esta condición no está cumplida. Es la más frecuente de todas las que fallan, y también la menos negociable: nadie estructura una emisión sobre una titularidad discutida."}]},{"t":"p","texto":[{"v":"Situaciones que la rompen habitualmente:"}]},{"t":"ul","items":[[{"v":"Herencias sin adjudicar","b":1},{"v":" o adjudicadas pero no inscritas."}],[{"v":"Proindivisos","b":1},{"v":" con copropietarios ilocalizables, en desacuerdo o simplemente no consultados."}],[{"v":"Sociedades con el libro registro de socios desactualizado","b":1},{"v":", o con participaciones cuya titularidad se apoya en documentos privados nunca elevados a público."}],[{"v":"Obras de arte sin cadena de procedencia documentada","b":1},{"v":", que es el equivalente en ese sector a no tener escritura."}],[{"v":"Créditos cedidos","b":1},{"v":" sin que la cesión se haya notificado o formalizado correctamente."}]]},{"t":"p","texto":[{"v":"Qué acredita la titularidad, según el tipo de activo","b":1}]},{"t":"tabla","cabecera":[[{"v":"Tipo de activo"}],[{"v":"Documento base"}],[{"v":"Qué se comprueba"}]],"filas":[[[{"v":"Inmobiliario"}],[{"v":"Nota simple registral actualizada"}],[{"v":"Titular inscrito, superficie, linderos, cargas"}]],[[{"v":"Deuda / créditos"}],[{"v":"Contrato de origen y cadena de cesiones"}],[{"v":"Validez de la cesión y notificación al deudor"}]],[[{"v":"Participaciones en pymes"}],[{"v":"Escritura y libro registro de socios"}],[{"v":"Titularidad, porcentajes, pactos vigentes"}]],[[{"v":"Arte y coleccionables"}],[{"v":"Procedencia, factura, certificados, informes periciales"}],[{"v":"Autenticidad y trazabilidad de la propiedad"}]]]},{"t":"h3","texto":[{"v":"Condición 2 — Cargas y restricciones identificadas y compatibles"}]},{"t":"p","texto":[{"v":"Una carga no impide tokenizar. Lo que impide tokenizar es "},{"v":"una carga que no sabías que tenías","b":1},{"v":", o una restricción contractual incompatible con la entrada de terceros."}]},{"t":"p","texto":[{"v":"Lo que hay que sacar a la luz antes de empezar:"}]},{"t":"ul","items":[[{"v":"Cargas registrales:","b":1},{"v":" hipotecas, embargos, servidumbres, usufructos, condiciones resolutorias."}],[{"v":"Derechos de terceros:","b":1},{"v":" opciones de compra, derechos de tanteo y retracto, arrendamientos con derechos legales asociados."}],[{"v":"Restricciones contractuales:","b":1},{"v":" pactos de socios con derechos de adquisición preferente o cláusulas de arrastre y acompañamiento."}],[{"v":"Cláusulas de cambio de control","b":1},{"v":" en la financiación existente."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso — la cláusula que más operaciones frena","bloques":[{"t":"p","texto":[{"v":"Si el activo está financiado, revisa la cláusula de cambio de control de tu contrato de préstamo antes que ninguna otra cosa. Muchas financiaciones permiten a la entidad declarar el vencimiento anticipado si la estructura de propiedad cambia sin su consentimiento. Descubrirlo con la emisión ya diseñada es la forma más cara de aprenderlo. Es una conversación que se tiene con el banco al principio, no al final."}]}]},{"t":"h3","texto":[{"v":"Condición 3 — Una valoración defendible, no una expectativa"}]},{"t":"p","texto":[{"v":"Aquí conviene ser directo: "},{"v":"si la única cifra que tienes es la que tú crees que vale, no tienes valoración.","b":1},{"v":" Tampoco lo es una oferta que te hicieron hace dos años, ni el precio de un inmueble parecido en el mismo portal, ni el valor contable heredado de una compra antigua."}]},{"t":"p","texto":[{"v":"Una valoración utilizable tiene cuatro atributos: "},{"v":"es independiente","b":1},{"v":" (la firma quien no cobra por el éxito de la operación), "},{"v":"tiene metodología explícita","b":1},{"v":", "},{"v":"tiene fecha","b":1},{"v":" y "},{"v":"es reciente","b":1},{"v":"."}]},{"t":"p","texto":[{"v":"Qué mira un valorador según el activo:","b":1}]},{"t":"ul","items":[[{"v":"Inmobiliario:","b":1},{"v":" tasación por sociedad homologada, con comparables, estado de conservación y situación arrendaticia. Atención a la vigencia: las tasaciones caducan."}],[{"v":"Deuda:","b":1},{"v":" calidad crediticia del deudor, garantías, histórico de impago de la cartera y plazo residual."}],[{"v":"Pymes:","b":1},{"v":" EBITDA normalizado, múltiplos del sector, dependencia de clientes o de personas clave, y deuda real."}],[{"v":"Arte:","b":1},{"v":" autenticidad acreditada, comparables de subasta reales —no precios de galería—, estado de conservación y liquidez histórica de ese artista y formato."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Una valoración inflada no es un atajo comercial: es un problema diferido. Todo el reparto de la emisión se construye sobre esa cifra, y la realidad aparece en el momento de vender el activo o de que un inversor quiera salir. Un valorador que te da malas noticias te está haciendo un favor."}]}]},{"t":"h3","texto":[{"v":"Condición 4 — Una estructura capaz de recibir inversores"}]},{"t":"p","texto":[{"v":"El activo tiene que poder alojarse en un vehículo limpio y auditable. En la práctica esto significa tres cosas:"}]},{"t":"p","texto":[{"v":"Aislamiento.","b":1},{"v":" El vehículo debe contener el activo del proyecto y poco más. Una sociedad que además tiene otra actividad, deudas ajenas al proyecto o gastos personales mezclados obliga a rediseñar la estructura desde cero. Es el motivo de rediseño más común que se encuentran los despachos."}]},{"t":"p","texto":[{"v":"Información fiable.","b":1},{"v":" Cuentas ordenadas y, según el perfil de inversor al que se aspire, auditadas. Obligaciones fiscales al corriente. Contratos relevantes localizables y vigentes."}]},{"t":"p","texto":[{"v":"Trazabilidad de la titularidad real.","b":1},{"v":" Los procesos de identificación exigen conocer quién está detrás de las sociedades: la persona física que en último término controla. Si la cadena societaria es opaca o hay socios que no van a someterse a identificación, la operación se detiene aquí. No es negociable, y no depende del proveedor que elijas."}]},{"t":"h3","texto":[{"v":"Condición 5 — Tamaño y economía que soporten los costes fijos"}]},{"t":"p","texto":[{"v":"Toda tokenización arrastra un "},{"v":"suelo de costes que no baja aunque el activo sea pequeño","b":1},{"v":": análisis y estructuración legal, valoración independiente, constitución del vehículo, infraestructura tecnológica, registro y custodia, auditoría y mantenimiento posterior."}]},{"t":"p","texto":[{"v":"Ese suelo es prácticamente el mismo para una emisión pequeña que para una mediana. Y ahí está la trampa: no existe un umbral universal por debajo del cual tokenizar sea imposible, pero sí existe "},{"v":"un porcentaje a partir del cual deja de tener sentido para ti","b":1},{"v":"."}]},{"t":"recuadro","tipo":"idea","titulo":"La regla práctica","bloques":[{"t":"p","texto":[{"v":"No preguntes «¿cuál es el mínimo para tokenizar?». Pregunta: "},{"v":"«¿qué porcentaje del importe que quiero captar se van a llevar los costes fijos del proceso?»","b":1},{"v":". Esa cifra —que un proveedor serio puede estimarte en una primera conversación— es la que decide, y la decides tú."}]},{"t":"p","texto":[{"v":"Recuerda además que hay costes recurrentes después de emitir: mantenimiento del registro, información periódica a los titulares y auditorías. La partida que casi todos los proyectos olvidan es la del año dos."}]}]},{"t":"p","texto":[{"v":"En la "},{"v":"Lección 5","b":1},{"v":" desglosamos las siete partidas de coste, qué es fijo y qué escala con el tamaño de la emisión, con los rangos observados en el mercado."}]},{"t":"h3","texto":[{"v":"La condición que no aparece en ninguna checklist: que haya alguien al otro lado"}]},{"t":"p","texto":[{"v":"Puedes cumplir las cinco anteriores de manera impecable y aun así encontrarte con una emisión que no se coloca, porque "},{"v":"fraccionar un activo no crea compradores","b":1},{"v":"."}]},{"t":"p","texto":[{"v":"Antes de avanzar, conviene tener una respuesta honesta a: ¿quién compraría esto y por qué motivo? ¿Existe demanda identificable para este tipo de activo, en esta ubicación, con este perfil de riesgo y este horizonte? ¿Tienes ya una base de posibles interesados o esperas que aparezca sola?"}]},{"t":"p","texto":[{"v":"Si la respuesta a la última pregunta es «espero que aparezca sola», eso es información valiosísima que conviene tener antes de gastar en estructuración, no después. Lo tratamos a fondo en la "},{"v":"Lección 6","b":1},{"v":"."}]},{"t":"h3","texto":[{"v":"Autoevaluación rápida: el semáforo de las cinco condiciones"}]},{"t":"tabla","cabecera":[[{"v":"Condición"}],[{"v":"🟢 Verde"}],[{"v":"🟡 Ámbar"}],[{"v":"🔴 Rojo"}]],"filas":[[[{"v":"1 · Titularidad","b":1}],[{"v":"Inscrita, sin discusión, un solo titular o todos identificados y de acuerdo"}],[{"v":"Copropiedad con todos localizados pero sin acuerdo formal"}],[{"v":"Herencia sin adjudicar, copropietario ilocalizable, procedencia no documentada"}]],[[{"v":"2 · Cargas","b":1}],[{"v":"Sin cargas, o cargas conocidas y compatibles"}],[{"v":"Financiación existente sin haber revisado el cambio de control"}],[{"v":"Embargos, litigios abiertos o derechos de terceros no resueltos"}]],[[{"v":"3 · Valoración","b":1}],[{"v":"Independiente, reciente y con metodología"}],[{"v":"Valoración existente pero antigua o parcial"}],[{"v":"Solo una cifra propia o una oferta pasada"}]],[[{"v":"4 · Estructura","b":1}],[{"v":"Vehículo limpio, cuentas ordenadas, titulares reales identificables"}],[{"v":"Sociedad con actividad mixta, subsanable"}],[{"v":"Opacidad societaria o socios que no aceptan identificación"}]],[[{"v":"5 · Tamaño","b":1}],[{"v":"Los costes fijos son una fracción asumible de lo que se capta"}],[{"v":"Al límite; depende del presupuesto final"}],[{"v":"Los costes fijos representan una parte desproporcionada"}]]]},{"t":"p","texto":[{"v":"Cómo leer tu resultado:","b":1},{"v":" cualquier rojo detiene el proceso hasta resolverlo. Los ámbares no lo detienen, pero se convierten en tu lista de tareas — y en tu principal palanca de negociación cuando pidas presupuesto, porque un expediente preparado se cotiza distinto que uno por preparar."}]},{"t":"h3","texto":[{"v":"Si has salido en rojo: qué significa realmente"}]},{"t":"p","texto":[{"v":"Casi ninguna condición fallida es definitiva. Son plazos, no sentencias:"}]},{"t":"ul","items":[[{"v":"Titularidad sin resolver","b":1},{"v":" → adjudicación de herencia, elevación a público, acuerdo entre copropietarios. Meses, no años, en la mayoría de casos."}],[{"v":"Cargas pendientes","b":1},{"v":" → negociación con la entidad financiera o cancelación registral de cargas ya satisfechas pero no levantadas, que es más frecuente de lo que parece."}],[{"v":"Sin valoración","b":1},{"v":" → encargar una. Es el punto de entrada más barato y el que más claridad aporta sobre todo lo demás."}],[{"v":"Estructura mezclada","b":1},{"v":" → segregación del activo a un vehículo limpio, con su coste fiscal y temporal, que conviene estimar antes."}],[{"v":"Tamaño insuficiente","b":1},{"v":" → agrupar varios activos en una misma emisión, o esperar. Ambas son decisiones legítimas."}]]},{"t":"p","texto":[{"v":"Y hay una quinta salida perfectamente razonable: "},{"v":"decidir que no","b":1},{"v":". Si al terminar este repaso concluyes que tu activo no encaja o que el esfuerzo no compensa, has ganado exactamente lo que venías a buscar. Un «no» bien fundamentado y tomado a tiempo vale más que una emisión mal preparada."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"Has terminado el "},{"v":"Nivel Principiante","b":1},{"v":". Sabes qué es tokenizar, quién interviene y en qué estado está tu activo."}]},{"t":"p","texto":[{"v":"El "},{"v":"Nivel Intermedio","b":1},{"v":" empieza con la pregunta que más miedo genera: "},{"v":"¿qué normativa te aplica?","b":1},{"v":" En la "},{"v":"Lección 4","b":1},{"v":" verás la frontera práctica entre un criptoactivo y un instrumento financiero, y por qué el inmobiliario, la deuda y las participaciones caen casi siempre del segundo lado — con todo lo que eso implica."}]}],"glosario":[{"termino":"Carga o gravamen","definicion":[{"v":"Derecho de un tercero que recae sobre un bien y limita la libre disposición de su propietario: una hipoteca, un embargo, un usufructo, una condición resolutoria. En bienes inmuebles constan en el Registro de la Propiedad y se consultan mediante nota simple; en otros activos, en los contratos y en los libros de la sociedad."}]},{"termino":"Titular real","definicion":[{"v":"Persona física que en último término posee o controla una entidad o una operación, por encima de las capas societarias intermedias. Identificarlo es una obligación de los procesos de prevención del blanqueo de capitales, y es la razón por la que ninguna emisión puede avanzar con una cadena de propiedad opaca."}]},{"termino":"Debida diligencia (due diligence)","definicion":[{"v":"Proceso de revisión ordenada del activo y de su titular antes de una operación: situación jurídica, cargas, contratos, cuentas, cumplimiento fiscal y riesgos identificables. Lo realiza quien va a asumir un riesgo —el estructurador, el inversor institucional, la entidad de registro— y su resultado condiciona las condiciones finales de la operación."}]}],"quiz":[{"enunciado":[{"v":"Heredaste un local comercial junto con tu hermano. Está inscrito a nombre de ambos, pero él lleva dos años sin responder a tus mensajes. ¿En qué situación estás?"}],"opciones":[[{"v":"Puedes tokenizar tu 50 %, que es tuyo y no requiere acuerdo"}],[{"v":"La titularidad no está en condiciones de soportar una emisión: no hay una voluntad única y acreditable de disponer del activo"}],[{"v":"Depende del valor del local"}],[{"v":"Es un problema del proveedor tecnológico, que debe resolverlo en la estructuración"}]],"correcta":1,"explicacion":[{"t":"p","texto":[{"v":"La condición de titularidad no exige solo "},{"v":"ser","i":1},{"v":" propietario, exige poder "},{"v":"disponer","b":1},{"v":" del activo de forma acreditable. En un proindiviso, el activo completo no puede aportarse a un vehículo sin el concurso de todos los copropietarios, y una cuota indivisa aislada es un objeto muy difícil de estructurar y aún más difícil de colocar. No es un problema de valor ni de tecnología: es el primer filtro, y se resuelve en el terreno legal —acuerdo, división de la cosa común o adjudicación— antes de que ningún proveedor pueda hacer nada."}]}]},{"enunciado":[{"v":"Un propietario afirma: «mi nave vale 1,2 millones, porque hace dos años me ofrecieron esa cantidad y no acepté». ¿Sirve como valoración?"}],"opciones":[[{"v":"Sí, una oferta real es la mejor prueba de valor de mercado"}],[{"v":"Sí, siempre que se documente la oferta por escrito"}],[{"v":"No: una valoración utilizable es independiente, metodológica, fechada y reciente; una oferta pasada no reúne esas condiciones"}],[{"v":"No, porque las ofertas rechazadas no tienen validez legal"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Una oferta pasada es un dato de contexto, no una valoración. Le faltan los cuatro atributos que hacen utilizable una cifra en una emisión: independencia de quien cobra por el éxito de la operación, metodología explícita y revisable, fecha, y vigencia. Dos años en un mercado inmobiliario pueden significar un movimiento relevante en cualquier dirección. Además, toda la arquitectura del reparto se construye sobre esa cifra: si no resiste el escrutinio de un tercero, el problema no desaparece, solo se aplaza al momento de vender."}]}]},{"enunciado":[{"v":"Sobre el tamaño mínimo de una emisión, ¿cuál es el planteamiento correcto?"}],"opciones":[[{"v":"Existe un umbral estándar en el sector por debajo del cual no se puede tokenizar"}],[{"v":"El tamaño es irrelevante, porque la tecnología escala sin coste"}],[{"v":"Lo determinante es qué proporción representan los costes fijos del proceso sobre el importe que se pretende captar, incluyendo los costes recurrentes posteriores a la emisión"}],[{"v":"Cuanto menor sea el activo, mejor, porque el ticket de entrada será más bajo"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"No hay un mínimo universal, porque depende del coste real de cada estructura y de lo que cada propietario considere asumible. Lo que sí es universal es el mecanismo: existe un suelo de costes fijos —legal, valoración, estructuración, registro, auditoría— que apenas varía con el tamaño de la emisión, y por tanto pesa proporcionalmente mucho más en las pequeñas. La opción B confunde el coste tecnológico, que sí escala bien, con el coste total del proceso, que está dominado por partidas humanas y regulatorias. Y conviene incluir en el cálculo el mantenimiento posterior, que es la partida más olvidada."}]}]}],"siguientePaso":{"titulo":"Has terminado el Nivel Principiante. Ahora ponle números a tu caso.","bloques":[{"t":"p","texto":[{"v":"El "},{"v":"Evaluador de Viabilidad de RWAdar","b":1},{"v":" recorre estas cinco condiciones contigo y te devuelve dos cosas: una "},{"v":"puntuación de madurez","b":1},{"v":" y un "},{"v":"mapa de brechas","b":1},{"v":" — qué te falta, en qué orden conviene resolverlo y qué documentación tendrás que reunir."}]},{"t":"p","texto":[{"v":"No te dice si debes tokenizar ni qué proveedor elegir. Te dice "},{"v":"en qué punto estás","b":1},{"v":"."}]},{"t":"p","texto":[{"v":"Privacidad por diseño:","b":1},{"v":" puedes completarlo de forma anónima. No necesitas identificar tu activo ni facilitar datos personales para ver el resultado. Si más adelante decides contactar con algún proveedor, se te pedirá un consentimiento específico para ese proveedor concreto, revocable en un clic."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]},{"t":"p","texto":[{"v":"¿Prefieres seguir aprendiendo antes? "},{"a":"leccion:marco-legal-cuando-tu-token-es-un-valor","v":"Continuar al Nivel Intermedio → Lección 4"}]}]},"notaLegal":[{"t":"p","texto":[{"v":"Las cinco condiciones y el semáforo de autoevaluación descritos en esta lección son una "},{"v":"herramienta educativa de orientación general","b":1},{"v":". No constituyen un dictamen sobre la viabilidad jurídica, fiscal o económica de ningún activo concreto, no sustituyen a una debida diligencia profesional y no deben utilizarse como base única para tomar una decisión. La calificación de cada situación depende de circunstancias particulares que solo puede valorar un profesional habilitado con acceso a la documentación completa."}]}]},
  {"slug":"marco-legal-cuando-tu-token-es-un-valor","modulo":4,"titulo":"El marco legal sin abogados: cuándo tu token es un valor y cuándo no","nivel":"intermedio","categoria":"Marco regulatorio","minutos":16,"resumen":"La calificación no depende de la tecnología ni del nombre que le pongas. Depende de una sola cosa: qué derecho estás vendiendo.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":true,"cta":"radar-capacidad-regulatoria","url":"https://rwadar.pages.dev/academy/marco-legal-cuando-tu-token-es-un-valor","tldr":[[{"v":"La calificación no depende de la tecnología ni del nombre que le pongas.","b":1},{"v":" Depende de una sola cosa: "},{"v":"qué derecho estás vendiendo","b":1},{"v":"."}],[{"v":"Si vendes propiedad fraccionada de un activo que renta, participación en beneficios o un derecho de crédito, casi siempre estás emitiendo un instrumento financiero","b":1},{"v":" — territorio MiFID II y ley española del mercado de valores, no MiCA."}],[{"v":"Caer en ese cajón no es una mala noticia.","b":1},{"v":" Es más lento y más caro, pero es lo que convierte tu emisión en algo defendible ante un inversor institucional y ante un supervisor."}]],"preambulo":[{"t":"recuadro","tipo":"idea","titulo":"Antes de empezar","bloques":[{"t":"p","texto":[{"v":"Esta es la lección con mayor carga normativa de toda la Academy y la que antes queda desactualizada. Te explicamos "},{"v":"cómo funciona el mecanismo de calificación","b":1},{"v":", no cómo calificar tu caso. La calificación concreta de una emisión solo puede hacerla un profesional habilitado con la documentación delante. Comprueba siempre la fecha de revisión que figura arriba."}]}]}],"cuerpo":[{"t":"h3","texto":[{"v":"La pregunta de la que cuelga absolutamente todo"}]},{"t":"p","texto":[{"v":"En la Lección 1 vimos que el token es la anotación de un derecho. Ahora toca la consecuencia práctica de aquella idea: "},{"v":"el régimen legal que te aplica lo determina el derecho que representas, no el software con el que lo registras","b":1},{"v":"."}]},{"t":"p","texto":[{"v":"Da igual que lo llames token, participación digital, unidad o cualquier otra cosa. El regulador mira a través de la etiqueta y pregunta: "},{"v":"¿qué recibe exactamente la persona que paga?","i":1}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"No preguntes «¿esto es un security token o un utility token?». Pregunta: "},{"v":"«¿qué derecho concreto adquiere quien compra, y de dónde espera obtener un beneficio?»","b":1},{"v":". La respuesta a esa pregunta decide en qué cajón caes, y el cajón decide todo lo demás: qué registro necesitas, qué información debes publicar, quién puede vender la emisión y dónde puede negociarse después."}]}]},{"t":"h3","texto":[{"v":"Los tres cajones"}]},{"t":"h4","texto":[{"v":"Cajón 1 · Instrumento financiero"}]},{"t":"p","texto":[{"v":"Es el territorio de MiFID II y, en España, de la ley del mercado de valores y de los servicios de inversión y su desarrollo reglamentario. Caes aquí cuando lo emitido es, en esencia, un valor negociable: participaciones en el capital de una sociedad, obligaciones o bonos, derechos de crédito, o derechos sobre los flujos que genera un activo gestionado por otro."}]},{"t":"p","texto":[{"v":"Las tres señales que apuntan a este cajón:","b":1}]},{"t":"ul","items":[[{"v":"El comprador "},{"v":"espera un rendimiento","b":1},{"v":" derivado de la gestión o el esfuerzo de un tercero, no de su propio uso del bien."}],[{"v":"Lo emitido es "},{"v":"fungible y transmisible","b":1},{"v":", pensado para circular entre inversores."}],[{"v":"Existe o se anticipa "},{"v":"un mercado","b":1},{"v":" donde esas unidades cambien de manos."}]]},{"t":"p","texto":[{"v":"Si las tres se cumplen, la conversación con tu despacho empieza por aquí, se llame como se llame el producto."}]},{"t":"h4","texto":[{"v":"Cajón 2 · Criptoactivo regulado por MiCA"}]},{"t":"p","texto":[{"v":"MiCA —el reglamento europeo de mercados de criptoactivos— cubre los criptoactivos que "},{"v":"no","b":1},{"v":" son instrumentos financieros: fichas referenciadas a activos, fichas de dinero electrónico y la categoría general de «otros criptoactivos», donde encajan los tokens de utilidad y las criptomonedas."}]},{"t":"p","texto":[{"v":"El propio reglamento excluye expresamente de su ámbito lo que ya es instrumento financiero. Es decir: los cajones 1 y 2 "},{"v":"no se solapan","b":1},{"v":". O una cosa o la otra."}]},{"t":"p","texto":[{"v":"En España, MiCA es plenamente aplicable desde el 1 de julio de 2026, al terminar el régimen transitorio para las entidades que ya venían operando."}]},{"t":"h4","texto":[{"v":"Cajón 3 · Fuera de ambos"}]},{"t":"p","texto":[{"v":"Piezas verdaderamente únicas y no fungibles —una obra concreta, un coleccionable irrepetible— quedan en principio fuera de MiCA por su carácter no fungible."}]},{"t":"recuadro","tipo":"aviso","titulo":"Atención — la trampa del fraccionamiento","bloques":[{"t":"p","texto":[{"v":"La exclusión de las piezas únicas decae cuando se emiten en serie o "},{"v":"se fraccionan en unidades intercambiables entre sí","b":1},{"v":". Y fraccionar es justamente lo que hace una tokenización. Si tu plan es dividir una obra de arte en mil participaciones que se compran esperando revalorización, es muy probable que no estés en el cajón 3 — sino en el 1. Esta es la confusión más frecuente en el arte tokenizado."}]}]},{"t":"h3","texto":[{"v":"Por qué el RWA «de verdad» cae casi siempre en el cajón 1"}]},{"t":"p","texto":[{"v":"Aquí está el mensaje que más dinero ahorra de toda esta lección. Buena parte del discurso comercial del sector habla el idioma de MiCA porque es el marco nuevo, mediático y aparentemente más accesible. Pero los activos que interesan a un dueño de patrimonio —un inmueble que renta, una cartera de préstamos, una participación en una pyme— generan derechos que son, por naturaleza, instrumentos financieros."}]},{"t":"p","texto":[{"v":"Traducido: "},{"v":"la mayoría de proyectos de tokenización de activos reales no se rigen por MiCA","b":1},{"v":". Se rigen por la normativa de valores de toda la vida, que es más exigente, más lenta y más cara, pero también mucho más sólida."}]},{"t":"p","texto":[{"v":"Si un proveedor te presenta tu emisión inmobiliaria como un producto MiCA y no menciona ni el registro autorizado ni las obligaciones de información al inversor, hay dos posibilidades: o ha calificado la operación de una forma que conviene revisar con un tercero independiente, o está describiendo un producto distinto del que tú crees estar comprando. En ambos casos, la conversación se detiene y se lleva a un despacho."}]},{"t":"h3","texto":[{"v":"Qué implica realmente caer en el cajón 1: las cuatro consecuencias"}]},{"t":"h4","texto":[{"v":"1. El registro deja de ser libre"}]},{"t":"p","texto":[{"v":"Cuando lo emitido son valores negociables representados mediante registro distribuido, la ley española exige que exista una "},{"v":"entidad responsable de la inscripción y el registro","b":1},{"v":" debidamente autorizada —típicamente entidades de crédito o empresas de servicios de inversión habilitadas para custodiar instrumentos financieros—, y un "},{"v":"documento de emisión","b":1},{"v":" que describa los valores y las características técnicas del registro."}]},{"t":"p","texto":[{"v":"Es la Condición que vimos en la Lección 2 y la que más candidatos elimina: no todo proveedor tecnológico puede ocupar esa posición."}]},{"t":"h4","texto":[{"v":"2. Aparece la obligación de informar (o una exención que hay que ganarse)"}]},{"t":"p","texto":[{"v":"Ofrecer valores al público activa, con carácter general, la obligación de publicar un "},{"v":"folleto","b":1},{"v":" aprobado por el supervisor. Existen exenciones, y la mayoría de emisiones pequeñas se apoyan en ellas:"}]},{"t":"ul","items":[[{"v":"Ofertas dirigidas "},{"v":"exclusivamente a inversores cualificados","b":1},{"v":"."}],[{"v":"Ofertas dirigidas a "},{"v":"menos de 150 inversores no cualificados","b":1},{"v":" por Estado miembro."}],[{"v":"Ofertas con un "},{"v":"importe mínimo elevado por inversor","b":1},{"v":"."}],[{"v":"Ofertas cuyo "},{"v":"importe total no supera un umbral","b":1},{"v":" en un periodo de doce meses."}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso — cifra en transición, compruébala","bloques":[{"t":"p","texto":[{"v":"A fecha de esta revisión (21 de agosto de 2026), el umbral de exención de folleto aplicable en España se ha situado tradicionalmente en "},{"v":"8 millones de euros","b":1},{"v":" en doce meses. La reforma europea conocida como "},{"v":"Listing Act","i":1},{"v":" amplía el margen que pueden fijar los Estados miembros "},{"v":"hasta 12 millones","b":1},{"v":", con efectos a partir de junio de 2026, y la adaptación de la norma española a ese nuevo margen ha estado pendiente de tramitación."}]},{"t":"p","texto":[{"v":"No dimensiones tu emisión sobre la cifra de esta lección.","b":1},{"v":" Confirma el umbral vigente en la web de la CNMV o con tu despacho antes de fijar el importe. Este recuadro es, además, un buen ejemplo de por qué toda lección de esta Academy lleva fecha de revisión visible."}]}]},{"t":"p","texto":[{"v":"Y una precisión que se malinterpreta constantemente: "},{"v":"la exención lo es de publicar folleto, no de todo lo demás.","b":1},{"v":" No te exime de la calificación como valor, ni de las reglas sobre quién puede comercializar, ni de la responsabilidad por la información que facilites. Incluso acogiéndote a una exención, suele ser necesario entregar algún documento informativo a los inversores."}]},{"t":"h4","texto":[{"v":"3. Vender la emisión es actividad reservada"}]},{"t":"p","texto":[{"v":"Captar, comercializar o colocar instrumentos financieros no lo puede hacer libremente cualquiera. Según la estructura, intervendrá una empresa de servicios de inversión, una "},{"v":"plataforma de financiación participativa autorizada","b":1},{"v":" —régimen europeo con su propio límite de captación por promotor en doce meses— o se articulará alguna exención."}]},{"t":"p","texto":[{"v":"Es el punto donde más proyectos se atascan: llegan con la emisión construida y descubren que no tienen forma legal de ofrecérsela a nadie."}]},{"t":"h4","texto":[{"v":"4. El mercado secundario no es libre"}]},{"t":"p","texto":[{"v":"Que un token sea técnicamente transferible no significa que pueda negociarse en cualquier sitio. La negociación de instrumentos financieros ocurre en infraestructuras autorizadas. Para las basadas en registro distribuido existe un "},{"v":"régimen piloto europeo","b":1},{"v":" específico, con condiciones y límites propios."}]},{"t":"p","texto":[{"v":"Es exactamente por esto que la promesa de «liquidez inmediata» merece tanto escepticismo. Lo desarrollamos en la Lección 6."}]},{"t":"h3","texto":[{"v":"Tu activo, tu cajón probable"}]},{"t":"tabla","cabecera":[[{"v":"Tu activo"}],[{"v":"Cajón más probable"}],[{"v":"Lo primero que hay que mirar"}]],"filas":[[[{"v":"Inmueble que genera rentas","b":1}],[{"v":"1 · Instrumento financiero"}],[{"v":"Estructura del vehículo, entidad de registro autorizada, vía de comercialización"}]],[[{"v":"Cartera de préstamos o facturas","b":1}],[{"v":"1 · Instrumento financiero"}],[{"v":"Validez de las cesiones, calidad crediticia, régimen de la oferta"}]],[[{"v":"Participación en una pyme","b":1}],[{"v":"1 · Instrumento financiero"}],[{"v":"Pactos de socios, régimen societario, límites del canal de captación"}]],[[{"v":"Obra de arte única, sin fraccionar","b":1}],[{"v":"3 · Posiblemente fuera"}],[{"v":"Autenticidad y procedencia; verificar que no haya serie ni fraccionamiento"}]],[[{"v":"Obra de arte fraccionada en participaciones","b":1}],[{"v":"1 · Muy probablemente instrumento financiero"}],[{"v":"La expectativa de revalorización cambia la naturaleza de la operación"}]],[[{"v":"Token de acceso o uso sin expectativa de rendimiento","b":1}],[{"v":"2 · MiCA"}],[{"v":"Obligaciones de libro blanco y comunicaciones publicitarias"}]]]},{"t":"p","texto":[{"v":"Orientación general con fines educativos. La calificación real depende del diseño concreto de cada operación.","i":1}]},{"t":"h3","texto":[{"v":"Los tres errores que más caros salen"}]},{"t":"p","texto":[{"v":"«Lo llamamos token de utilidad y así evitamos la normativa de valores.»","b":1},{"br":1},{"v":"La etiqueta no decide nada. Si quien compra espera un rendimiento derivado de la gestión de otro, el nombre comercial es irrelevante. Este planteamiento no reduce el riesgo: lo concentra, porque añade a la infracción de fondo un problema de información engañosa al inversor."}]},{"t":"p","texto":[{"v":"«Solo se lo ofrezco a gente de mi entorno, así que no es una oferta pública.»","b":1},{"br":1},{"v":"Las exenciones por número de inversores o por importe existen, pero tienen condiciones precisas que hay que cumplir y acreditar, y se agotan. Además, exención no equivale a ausencia de obligaciones. Es una vía perfectamente válida, pero se diseña con un despacho, no se improvisa."}]},{"t":"p","texto":[{"v":"«La plataforma tiene sede fuera de la UE, así que la normativa española no aplica.»","b":1},{"br":1},{"v":"Lo determinante no es dónde esté el proveedor, sino "},{"v":"hacia dónde se dirige la oferta y dónde residen los inversores","b":1},{"v":". Una emisión ofrecida activamente a residentes en España atrae la normativa española, con independencia del domicilio social de quien la instrumenta."}]},{"t":"h3","texto":[{"v":"Qué llevar a la primera reunión con tu despacho"}]},{"t":"p","texto":[{"v":"Cinco datos que abaratan y aceleran cualquier análisis legal:"}]},{"t":"ol","items":[[{"v":"Qué derecho quieres vender exactamente:","b":1},{"v":" propiedad indirecta, participación en rentas, crédito con interés, o combinación."}],[{"v":"A quién quieres ofrecérselo:","b":1},{"v":" minoristas, cualificados, o ambos."}],[{"v":"En qué países residen esos inversores.","b":1}],[{"v":"Cuánto quieres captar","b":1},{"v":" y en cuánto tiempo."}],[{"v":"Si aspiras a que exista mercado secundario","b":1},{"v":" o basta con una tenencia a vencimiento."}]]},{"t":"p","texto":[{"v":"Con esas cinco respuestas, un despacho puede orientarte sobre el cajón, la vía de oferta y el orden de magnitud del proceso. Sin ellas, cualquier presupuesto que recibas será una estimación a ciegas."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"Ya sabes qué régimen te aplica y por qué. Falta la pregunta que decide si el proyecto sigue adelante: "},{"v":"cuánto cuesta y cuánto tarda todo esto","b":1},{"v":". En la "},{"v":"Lección 5","b":1},{"v":" desglosamos las siete partidas reales de un presupuesto de tokenización, cuáles son fijas, cuáles escalan con el tamaño de la emisión y cuál es la que casi todos los proyectos olvidan."}]}],"glosario":[{"termino":"Valor negociable","definicion":[{"v":"Categoría de instrumento financiero que agrupa las clases de valores susceptibles de ser negociados en el mercado de capitales: acciones y participaciones equivalentes, bonos y obligaciones, y otros valores que otorgan derecho a adquirirlos o que dan lugar a una liquidación en efectivo. Que un valor se represente mediante registro distribuido no altera su condición de valor negociable."}]},{"termino":"Folleto","definicion":[{"v":"Documento informativo, sujeto a aprobación del supervisor, que debe publicarse con carácter general antes de ofrecer valores al público o admitirlos a negociación. Recoge la información necesaria para que un inversor evalúe el emisor, el activo, los derechos que adquiere y los riesgos. Existen exenciones tasadas, que eximen de publicarlo pero no del resto de obligaciones."}]},{"termino":"Inversor cualificado","definicion":[{"v":"Categoría de inversor —entidades financieras, grandes empresas y determinadas personas que solicitan expresamente ese tratamiento y acreditan conocimientos y patrimonio— a la que se presume capacidad para evaluar riesgos por sí misma. Las ofertas dirigidas exclusivamente a inversores cualificados están sujetas a un régimen de información menos exigente."}]}],"quiz":[{"enunciado":[{"v":"Vas a emitir 2.000 unidades digitales que dan a su titular derecho a percibir el 80 % de las rentas netas de un edificio que gestiona tu sociedad. En el material comercial se denominan «tokens de utilidad inmobiliaria». ¿Cómo se califica probablemente la operación?"}],"opciones":[[{"v":"Criptoactivo bajo MiCA, porque así lo denomina el material comercial"}],[{"v":"Fuera de toda regulación, porque el subyacente es un bien físico"}],[{"v":"Instrumento financiero, porque el comprador espera un rendimiento derivado de la gestión de un tercero sobre unidades fungibles y transmisibles"}],[{"v":"Depende de la cadena de bloques utilizada"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Se dan las tres señales del cajón 1: expectativa de rendimiento generado por la gestión ajena, unidades fungibles y transmisibles, y vocación de circular entre inversores. El nombre comercial no altera la calificación —de hecho, denominar «utilidad» a algo que funcionalmente es una participación en rentas añade un problema de información al inversor sobre el problema de fondo—. Tampoco la tecnología: el reglamento europeo de criptoactivos excluye expresamente de su ámbito lo que ya es instrumento financiero, de modo que los dos regímenes no se solapan."}]}]},{"enunciado":[{"v":"Tu emisión se acoge a una exención que te libera de publicar folleto. ¿Qué significa exactamente?"}],"opciones":[[{"v":"Que la emisión deja de considerarse un instrumento financiero"}],[{"v":"Que no necesitas entidad de registro autorizada ni canal de comercialización habilitado"}],[{"v":"Que no estás obligado a publicar el folleto, pero mantienes la calificación como valor y el resto de obligaciones, incluida la responsabilidad por la información que facilites"}],[{"v":"Que puedes ofrecer la emisión libremente a cualquier inversor de cualquier país"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Es el malentendido más extendido del sector. La exención tiene un objeto muy concreto y limitado: te libera de elaborar y publicar el folleto. No cambia la naturaleza jurídica de lo emitido, no elimina el requisito de registro cuando resulta aplicable, no habilita a cualquiera para comercializar la emisión y no te exime de responder por la información que entregues a los inversores —de hecho, suele seguir siendo necesario facilitar algún documento informativo—. Las exenciones además tienen condiciones que hay que cumplir y acreditar, y se agotan."}]}]},{"enunciado":[{"v":"Una plataforma domiciliada fuera de la Unión Europea te propone emitir y ofrecer tus tokens a inversores residentes en España, argumentando que «al no estar establecida en la UE, la normativa española no le resulta aplicable». ¿Cómo debes interpretarlo?"}],"opciones":[[{"v":"Es correcto: el régimen aplicable es el del domicilio del proveedor"}],[{"v":"Es correcto solo si los servidores están fuera de la UE"}],[{"v":"Es un argumento que no se sostiene: lo determinante es hacia dónde se dirige la oferta y dónde residen los inversores destinatarios"}],[{"v":"Es correcto siempre que los inversores firmen una renuncia expresa"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"El criterio de conexión relevante en la comercialización de instrumentos financieros no es el domicilio social del proveedor ni la ubicación de su infraestructura técnica, sino el mercado al que se dirige activamente la oferta y la residencia de los destinatarios. Una emisión promocionada hacia residentes en España atrae la normativa española y europea aplicable. Y la opción D señala otro error frecuente: la protección del inversor minorista no es un derecho del que se pueda disponer mediante una renuncia contractual."}]}]}],"siguientePaso":{"titulo":"Ahora ya sabes qué preguntarle a un proveedor","bloques":[{"t":"p","texto":[{"v":"Si tu proyecto cae en el cajón 1 —y la mayoría de los activos reales caen ahí—, necesitas trabajar con actores que tengan "},{"v":"capacidad regulatoria real","b":1},{"v":", no solo capacidad técnica: una entidad de registro autorizada y un canal de comercialización habilitado."}]},{"t":"p","texto":[{"v":"El radar de RWAdar verifica a cada plataforma frente a cuatro criterios, y el primero es precisamente la "},{"v":"supervisión regulatoria","b":1},{"v":". Puedes filtrar por categoría —marketplace, emisor, infraestructura— y por región, y consultar la sección "},{"v":"Fuera del radar","i":1},{"v":", donde publicamos con motivo y fuente las plataformas que no superan el filtro."}]},{"t":"p","texto":[{"a":"radar-capacidad-regulatoria","v":"Abrir el radar y filtrar por capacidad regulatoria"}]},{"t":"p","texto":[{"v":"¿Aún no has diagnosticado tu activo? El "},{"v":"Evaluador de Viabilidad","b":1},{"v":" te dice en qué punto estás y qué te falta. Puedes completarlo de forma anónima, sin identificar tu activo ni facilitar datos personales."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]}]},"notaLegal":[{"t":"p","texto":[{"v":"Aviso reforzado para esta lección.","b":1},{"v":" El contenido regulatorio aquí expuesto es una "},{"v":"explicación general y simplificada","b":1},{"v":" de un marco normativo complejo, en evolución y sujeto a interpretación por las autoridades competentes. Las categorías, umbrales, exenciones y regímenes descritos pueden haber cambiado con posterioridad a la fecha de revisión indicada. Ninguna de las clasificaciones orientativas incluidas —en particular la tabla de «tu cajón probable»— constituye una calificación jurídica de operación alguna. La calificación de una emisión concreta depende del diseño específico de los derechos emitidos, del perfil de los destinatarios y de las jurisdicciones implicadas, y "},{"v":"solo puede realizarla un profesional habilitado con acceso a la documentación completa","b":1},{"v":"."}]}]},
  {"slug":"cuanto-cuesta-tokenizar","modulo":5,"titulo":"Cuánto cuesta y cuánto tarda: la anatomía de un presupuesto de tokenización","nivel":"intermedio","categoria":"Economía del proyecto","minutos":15,"resumen":"No existe una tarifa única, y quien te da un precio antes de saber qué emites y a quién no está presupuestando: está captando.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"radar-comparador","url":"https://rwadar.pages.dev/academy/cuanto-cuesta-tokenizar","tldr":[[{"v":"No existe una tarifa única, y quien te da un precio antes de saber qué emites y a quién no está presupuestando: está captando.","b":1}],[{"v":"El coste se reparte en siete partidas y la mayoría son fijas.","b":1},{"v":" Por eso pesan desproporcionadamente en las emisiones pequeñas, tal y como viste en la Lección 3."}],[{"v":"La partida que hunde proyectos no es la de emitir. Es la del año dos:","b":1},{"v":" el mantenimiento recurrente que casi nadie incluye en la conversación inicial."}]],"preambulo":[],"cuerpo":[{"t":"h3","texto":[{"v":"Por qué esta lección no te da una cifra"}]},{"t":"p","texto":[{"v":"Podríamos publicar un rango en euros. Sería lo más cómodo, sería lo que más se comparte y sería, en la práctica, información falsa."}]},{"t":"p","texto":[{"v":"El coste de una tokenización depende de decisiones que todavía no has tomado: qué derecho vas a emitir, a qué inversores te diriges, en cuántos países, si necesitas folleto o te acoges a una exención, si tu activo ya está en un vehículo limpio o hay que segregarlo, cuántos titulares vas a administrar y durante cuánto tiempo. Cambia cualquiera de esas variables y el presupuesto se mueve en un orden de magnitud, no en un porcentaje."}]},{"t":"p","texto":[{"v":"Publicar una cifra media serviría para dos cosas, ambas malas: para que un proveedor la use como ancla comercial —«mira, nosotros estamos por debajo de la media del sector»— y para que tú descartes o aceptes un proyecto por un número que no tiene nada que ver con tu caso."}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"Lo que necesitas no es un precio de referencia. Es "},{"v":"entender de qué está hecho un presupuesto","b":1},{"v":", para poder pedirlo desglosado, compararlo con otro y detectar lo que falta. Esta lección te da eso."}]}]},{"t":"h3","texto":[{"v":"Las siete partidas de un presupuesto de tokenización"}]},{"t":"h4","texto":[{"v":"1 · Análisis y estructuración legal"}]},{"t":"p","texto":[{"v":"Es la partida que decide todas las demás y la que nunca conviene recortar. Incluye el análisis de calificación que viste en la Lección 4, el diseño de la estructura, la redacción del documento de emisión y de los contratos, y la definición de la vía de oferta."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" fija. No baja porque tu activo sea pequeño."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" dirigirse a inversores de varios países, activos con cargas o titularidad compleja, estructuras societarias preexistentes que hay que reordenar."},{"br":1},{"v":"Cómo pedirla:","b":1},{"v":" presupuesto por fases, con un alcance escrito de qué entregables incluye cada una."}]},{"t":"h4","texto":[{"v":"2 · Documentación de la oferta"}]},{"t":"p","texto":[{"v":"Aquí se decide buena parte del coste total del proyecto. Si tu emisión requiere "},{"v":"folleto","b":1},{"v":", esta partida se multiplica: es un documento extenso, sujeto a aprobación del supervisor y con un proceso de revisión que consume tiempo y honorarios. Si te acoges a una exención, el trabajo es sensiblemente menor — pero no desaparece, porque suele seguir siendo necesario entregar algún documento informativo a los inversores."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" semifija, con un salto brusco según la vía elegida."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" la necesidad de folleto; el número de jurisdicciones destinatarias."}]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Esta es la razón por la que el diseño de la oferta —a quién, cuántos, cuánto— debe decidirse "},{"v":"antes","b":1},{"v":" de pedir presupuestos, y no después. Dos emisiones idénticas en lo económico pueden diferir enormemente en coste según a quién se dirijan."}]}]},{"t":"h4","texto":[{"v":"3 · Valoración independiente"}]},{"t":"p","texto":[{"v":"Ya viste en la Lección 3 qué hace utilizable una valoración. Aquí lo relevante es que se cotiza por activo y por metodología, y que "},{"v":"caduca","b":1},{"v":": si el proceso se alarga, puede haber que renovarla."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" fija por activo, potencialmente repetible."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" activos múltiples o heterogéneos, categorías que exigen peritaje especializado —arte, maquinaria, activos singulares—."}]},{"t":"h4","texto":[{"v":"4 · Vehículo y coste fiscal de la aportación"}]},{"t":"p","texto":[{"v":"Constituir o adaptar la sociedad que va a poseer el activo tiene un coste societario modesto y previsible. El que sorprende es otro: "},{"v":"aportar un activo a una sociedad es una operación con consecuencias fiscales","b":1},{"v":", que varían según el tipo de bien, la forma de la aportación y el régimen aplicable."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" variable, y potencialmente la más alta de todas si se planifica mal."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" segregar un inmueble de un patrimonio mayor, plusvalías latentes, reorganizaciones societarias."}]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso — la sorpresa más cara del proceso","bloques":[{"t":"p","texto":[{"v":"Muchos propietarios descubren esta partida cuando la estructura ya está diseñada. Consulta el impacto fiscal de la aportación con un asesor fiscal "},{"v":"al principio","b":1},{"v":", no al final: en algunos casos condiciona la estructura entera, e incluso la decisión de seguir adelante."}]}]},{"t":"h4","texto":[{"v":"5 · Tecnología"}]},{"t":"p","texto":[{"v":"Desarrollo o configuración de los contratos inteligentes, plataforma de titulares, integraciones con los procesos de identificación y con el registro."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" semifija. Es la partida donde más rango hay entre una solución estándar configurada y un desarrollo a medida."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" reglas de transmisión poco convencionales, automatismos de reparto, integraciones con sistemas propios."}]},{"t":"p","texto":[{"v":"Una observación útil: en la mayoría de proyectos de tamaño medio, la tecnología "},{"v":"no","b":1},{"v":" es la partida dominante. Cuando un presupuesto está dominado por el desarrollo, suele indicar que se está construyendo a medida algo que existe estandarizado, o que las partidas legales están infravaloradas."}]},{"t":"h4","texto":[{"v":"6 · Registro y custodia"}]},{"t":"p","texto":[{"v":"Cuando lo emitido son valores negociables, interviene la entidad responsable del registro y la custodia que viste en las Lecciones 2 y 4. Estas entidades "},{"v":"publican sus propias tarifas","b":1},{"v":", lo que las convierte en una de las pocas partidas que puedes verificar por tu cuenta antes de negociar nada."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" fija de alta más "},{"v":"recurrente","b":1},{"v":" mientras la emisión viva."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" número de titulares, frecuencia de movimientos, servicios adicionales de administración."}]},{"t":"h4","texto":[{"v":"7 · Auditoría y cumplimiento continuo"}]},{"t":"p","texto":[{"v":"Agrupa la auditoría técnica del contrato inteligente, la auditoría de cuentas del vehículo cuando procede, y los procesos permanentes de identificación de inversores y prevención del blanqueo."}]},{"t":"p","texto":[{"v":"Naturaleza:","b":1},{"v":" parcialmente inicial, mayoritariamente "},{"v":"recurrente","b":1},{"v":"."},{"br":1},{"v":"Qué la dispara:","b":1},{"v":" número y rotación de inversores, perfil internacional de los titulares, exigencias del inversor institucional."}]},{"t":"h3","texto":[{"v":"El error del año dos"}]},{"t":"p","texto":[{"v":"Casi todas las conversaciones comerciales se centran en el coste de "},{"v":"llegar a emitir","b":1},{"v":". Pero una emisión viva consume recursos todos los años, y ese es el número que decide si el proyecto tiene sentido a largo plazo."}]},{"t":"tabla","cabecera":[[{"v":"Partida"}],[{"v":"¿Se repite?"}],[{"v":"Cuándo aparece"}]],"filas":[[[{"v":"Estructuración legal"}],[{"v":"No, salvo cambios"}],[{"v":"Una vez"}]],[[{"v":"Documentación de la oferta"}],[{"v":"Solo si hay nuevas emisiones"}],[{"v":"Una vez por oferta"}]],[[{"v":"Valoración"}],[{"v":"Sí","b":1}],[{"v":"Renovación periódica, y siempre que caduque"}]],[[{"v":"Vehículo y fiscalidad"}],[{"v":"Constitución una vez; "},{"v":"obligaciones societarias y fiscales, siempre","b":1}],[{"v":"Anual"}]],[[{"v":"Tecnología"}],[{"v":"Desarrollo una vez; "},{"v":"mantenimiento y soporte, siempre","b":1}],[{"v":"Anual"}]],[[{"v":"Registro y custodia"}],[{"v":"Sí","b":1}],[{"v":"Anual o por movimiento"}]],[[{"v":"Auditoría y cumplimiento"}],[{"v":"Sí","b":1}],[{"v":"Anual y continuo"}]]]},{"t":"recuadro","tipo":"idea","titulo":"La pregunta que hay que hacer en toda reunión","bloques":[{"t":"p","texto":[{"v":"«¿Cuánto me cuesta esto el segundo año, sin emitir nada nuevo?»","i":1},{"br":1},{"v":"Si el proveedor no tiene esa cifra preparada, no ha presupuestado el proyecto: ha presupuestado el lanzamiento."}]}]},{"t":"h3","texto":[{"v":"Los plazos: qué determina realmente el calendario"}]},{"t":"p","texto":[{"v":"Los rangos que circulan —«de unas semanas a varios meses»— son ciertos y poco útiles, porque el calendario no lo marca la tecnología. Lo marcan cuatro cosas, en este orden:"}]},{"t":"p","texto":[{"v":"1. El estado de tu activo.","b":1},{"v":" Todo lo que salió en ámbar o rojo en el semáforo de la Lección 3 es tiempo: adjudicar una herencia, levantar una carga, negociar con el banco, encargar una valoración. Es la fase más larga y la única que puedes adelantar "},{"v":"antes","b":1},{"v":" de contratar a nadie."}]},{"t":"p","texto":[{"v":"2. La vía de oferta.","b":1},{"v":" Si necesitas folleto, ese proceso domina el calendario. Si te acoges a una exención, el cuello de botella se desplaza a la estructuración."}]},{"t":"p","texto":[{"v":"3. La incorporación de terceros regulados.","b":1},{"v":" Contratar entidad de registro y canal de comercialización tiene sus propios procesos de admisión y debida diligencia sobre ti, que no se aceleran pagando más."}]},{"t":"p","texto":[{"v":"4. La construcción técnica.","b":1},{"v":" Casi siempre es la fase más corta, y casi siempre es de la que más se habla."}]},{"t":"recuadro","tipo":"idea","titulo":"La consecuencia práctica","bloques":[{"t":"p","texto":[{"v":"Cada semana que dediques ahora a preparar documentación es una semana que no pagarás después a tarifa profesional. Prepararse es la única palanca de plazo y de coste que está enteramente en tus manos."}]}]},{"t":"h3","texto":[{"v":"Cómo pedir un presupuesto que puedas comparar"}]},{"t":"p","texto":[{"v":"Envía a cada proveedor exactamente la misma información y exige exactamente el mismo formato de respuesta. Si no, no estarás comparando: estarás eligiendo al que mejor escribe."}]},{"t":"p","texto":[{"v":"Lo que tú entregas (idéntico a todos):","b":1}]},{"t":"ol","items":[[{"v":"Tipo de activo, valor orientativo y situación registral."}],[{"v":"Qué derecho quieres emitir y a quién quieres dirigirte."}],[{"v":"Países de residencia de los inversores previstos."}],[{"v":"Importe a captar y horizonte temporal."}],[{"v":"Si aspiras o no a mercado secundario."}]]},{"t":"p","texto":[{"v":"Lo que exiges recibir (idéntico de todos):","b":1}]},{"t":"ol","items":[[{"v":"Desglose "},{"v":"por las siete partidas","b":1},{"v":" de esta lección, indicando cuáles ejecutan ellos y cuáles subcontratan y a quién."}],[{"v":"Coste recurrente anual estimado a partir del año dos."}],[{"v":"Qué queda "},{"v":"fuera","b":1},{"v":" del presupuesto y en qué supuestos aparecerían costes adicionales."}]],"inicio":6},{"t":"h3","texto":[{"v":"Cinco señales de alarma en un presupuesto"}]},{"t":"ul","items":[[{"v":"Un precio cerrado global antes de la estructuración legal.","b":1},{"v":" No es posible saber el precio sin saber qué se emite. Un precio así o lleva un margen de seguridad enorme, o se ampliará después."}],[{"v":"Una única línea de «servicios de tokenización».","b":1},{"v":" Sin desglose no hay comparación posible, y lo que no está desglosado suele ser lo que no está incluido."}],[{"v":"Ausencia de la partida de registro y custodia","b":1},{"v":" en una emisión que es un valor. Indica que esa pieza no está resuelta."}],[{"v":"Silencio sobre el coste recurrente.","b":1},{"v":" Ver más arriba."}],[{"v":"Un presupuesto dominado por el desarrollo tecnológico","b":1},{"v":" con las partidas legales reducidas al mínimo. Suele señalar dónde está el negocio del proveedor, no dónde está el riesgo de tu proyecto."}]]},{"t":"h3","texto":[{"v":"La cuenta que realmente decide"}]},{"t":"p","texto":[{"v":"Vuelve a la regla de la Lección 3, ahora con los datos en la mano:"}]},{"t":"p","texto":[{"v":"Suma de costes fijos iniciales ÷ importe que pretendes captar = el porcentaje que decide.","b":1}]},{"t":"p","texto":[{"v":"Y después haz la segunda cuenta, la que casi nadie hace:"}]},{"t":"p","texto":[{"v":"Coste recurrente anual ÷ ingreso neto anual esperado del activo.","b":1}]},{"t":"p","texto":[{"v":"Si la segunda cifra es incómoda, el proyecto no falla al emitir: falla al tercer año, cuando el mantenimiento se come el rendimiento y ya hay inversores dentro. Detectarlo ahora es gratis."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"Ya sabes qué te aplica y cuánto cuesta. Queda la promesa que más se repite en este sector y menos se cumple: "},{"v":"la liquidez","b":1},{"v":". En la "},{"v":"Lección 6","b":1},{"v":" verás por qué fraccionar no crea compradores, qué condiciones reales producen un mercado secundario y qué preguntas concretas hacerle a un proveedor que te promete que podrás vender cuando quieras."}]}],"glosario":[{"termino":"Aportación no dineraria","definicion":[{"v":"Entrega de un bien —un inmueble, una cartera de créditos, participaciones— a una sociedad a cambio de recibir participaciones o acciones de esta. Es el mecanismo habitual para colocar un activo dentro del vehículo que después se tokeniza, y tiene consecuencias fiscales propias que dependen del bien aportado y del régimen aplicable."}]},{"termino":"Presupuesto cerrado por partidas (fee cap)","definicion":[{"v":"Cotización desglosada por conceptos en la que cada partida lleva asociado un importe máximo, de modo que las desviaciones no se trasladan automáticamente al cliente. Es el formato que permite comparar ofertas entre sí y el que un proveedor solvente puede ofrecer una vez definido el alcance."}]},{"termino":"Coste recurrente de mantenimiento","definicion":[{"v":"Conjunto de gastos que la emisión genera cada año una vez viva: registro y custodia, información periódica a titulares, procesos de identificación, auditorías, obligaciones societarias y fiscales, y soporte tecnológico. Es independiente de que se realicen o no nuevas emisiones."}]}],"quiz":[{"enunciado":[{"v":"En la primera llamada, antes de conocer qué derecho vas a emitir ni a qué inversores te diriges, un proveedor te ofrece un precio cerrado global para «tokenizar tu inmueble». ¿Cómo debes interpretarlo?"}],"opciones":[[{"v":"Como una ventaja competitiva: transparencia de precio desde el inicio"}],[{"v":"Como una señal de alarma: el coste depende de decisiones de estructura que aún no se han tomado, así que ese precio o incorpora un margen elevado o se ampliará después"}],[{"v":"Como algo indiferente, siempre que el precio parezca razonable"}],[{"v":"Como prueba de que el proveedor domina el proceso"}]],"correcta":1,"explicacion":[{"t":"p","texto":[{"v":"El precio de una tokenización está determinado por variables que se fijan en la estructuración: qué derecho se emite, a qué inversores, en cuántas jurisdicciones, con folleto o con exención, con qué vehículo y con qué impacto fiscal. Ofrecer una cifra cerrada antes de resolver eso solo puede significar dos cosas, y ninguna te beneficia: que el proveedor ha cargado un colchón para cubrirse, o que el presupuesto se revisará al alza cuando aparezcan las partidas reales. El formato correcto es un presupuesto por fases al inicio y un cierre por partidas cuando el alcance esté definido."}]}]},{"enunciado":[{"v":"Comparas dos presupuestos. Uno es sensiblemente más barato, pero no incluye ninguna línea de registro y custodia ni de cumplimiento continuo, y tu emisión se ha calificado como valor negociable. ¿Qué conclusión es la correcta?"}],"opciones":[[{"v":"El más barato es más eficiente y conviene elegirlo"}],[{"v":"La diferencia se explica por el margen comercial de cada proveedor"}],[{"v":"No son comparables: al presupuesto barato le faltan partidas obligatorias, que aparecerán después o indican que la operación no está bien planteada"}],[{"v":"Conviene negociar con el caro usando el barato como referencia"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Cuando lo emitido es un valor negociable, la intervención de una entidad de registro y custodia autorizada y los procesos de identificación de inversores no son opcionales. Un presupuesto que los omite no es más barato: está incompleto. Y su ausencia es además un indicio sobre cómo está planteada la operación, que conviene aclarar antes que el precio. La opción D describe una táctica de negociación que, aplicada sobre presupuestos no equivalentes, lleva a elegir mal creyendo que se ha negociado bien."}]}]},{"enunciado":[{"v":"¿Cuál es la partida que con más frecuencia se omite en la conversación comercial inicial y más proyectos compromete a medio plazo?"}],"opciones":[[{"v":"El desarrollo de los contratos inteligentes"}],[{"v":"La valoración independiente del activo"}],[{"v":"El coste recurrente de mantenimiento a partir del año dos"}],[{"v":"La constitución de la sociedad vehículo"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"El discurso comercial se organiza alrededor del coste de llegar a emitir, porque es el que cierra la venta. Pero una emisión viva consume recursos cada año: registro y custodia, información a titulares, procesos de identificación, auditorías y obligaciones societarias y fiscales. Si ese coste recurrente representa una proporción elevada del rendimiento neto anual del activo, el problema no se manifiesta en el lanzamiento sino al segundo o tercer año, cuando ya hay inversores dentro y las alternativas son mucho más limitadas. La pregunta que lo revela es directa: "},{"v":"¿cuánto cuesta esto el año que viene sin emitir nada nuevo?","i":1}]}]}],"siguientePaso":{"titulo":"Compara con los mismos criterios, no con la mejor presentación","bloques":[{"t":"p","texto":[{"v":"Ahora tienes las siete partidas y el formato de solicitud. Lo que falta es a quién enviárselo."}]},{"t":"p","texto":[{"v":"En el radar de RWAdar puedes "},{"v":"comparar hasta tres plataformas en paralelo","b":1},{"v":", filtrar por región, tipo de activo, nivel de acceso y categoría, y exportar los datos para llevarlos a tu propia hoja de comparación. También publicamos la sección "},{"v":"Fuera del radar","i":1},{"v":", con las plataformas que no superan nuestros cuatro criterios de verificación, su motivo y su fuente."}]},{"t":"p","texto":[{"a":"radar-comparador","v":"Abrir el comparador del radar"}]},{"t":"p","texto":[{"v":"Y recuerda la palanca que solo depende de ti: cuanto más preparado esté tu expediente, menos horas profesionales pagarás. El "},{"v":"Evaluador de Viabilidad","b":1},{"v":" te dice exactamente qué te falta. Puedes completarlo de forma anónima, sin identificar tu activo ni facilitar datos personales."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]}]},"notaLegal":[{"t":"p","texto":[{"v":"Sobre los costes.","b":1},{"v":" Esta lección describe de forma general la "},{"v":"estructura","b":1},{"v":" de un presupuesto de tokenización y "},{"v":"no publica precios, rangos ni estimaciones económicas","b":1},{"v":", precisamente porque el coste depende del diseño concreto de cada operación. Nada de lo aquí expuesto debe interpretarse como una referencia de mercado, una valoración de la razonabilidad del precio de ningún proveedor ni una base para dimensionar una operación. Las consideraciones sobre el impacto fiscal de la aportación de activos son una advertencia general: su determinación corresponde a un asesor fiscal con conocimiento del caso."}]}]},
  {"slug":"liquidez-como-evaluarla","modulo":6,"titulo":"La liquidez es la promesa más incumplida del sector: cómo evaluarla antes de creerla","nivel":"intermedio","categoria":"Gestión de riesgos","minutos":13,"resumen":"Fraccionar un activo crea divisibilidad, no compradores. La liquidez es un hecho de mercado, no una propiedad técnica del token.","publicado":true,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"radar-nivel-acceso","url":"https://rwadar.pages.dev/academy/liquidez-como-evaluarla","tldr":[[{"v":"Fraccionar un activo crea divisibilidad, no compradores.","b":1},{"v":" La liquidez es un hecho de mercado, no una propiedad técnica del token."}],[{"v":"Cuatro condiciones producen un mercado secundario real, y la tecnología no aporta ninguna de las cuatro.","b":1},{"v":" Aporta otra cosa distinta, que también tiene valor."}],[{"v":"La mayoría de emisiones de activos reales nacen ilíquidas, y así deben presentarse.","b":1},{"v":" Prometer lo contrario no es un exceso comercial: es un problema de información al inversor del que responde el emisor — es decir, tú."}]],"preambulo":[],"cuerpo":[{"t":"h3","texto":[{"v":"La frase fundacional del sector"}]},{"t":"p","texto":[{"v":"«Convierte tu activo ilíquido en un activo líquido.»","i":1}]},{"t":"p","texto":[{"v":"Es probablemente la frase más repetida en la tokenización de activos reales, y la que más expectativas ha generado. También es, en la mayoría de los casos, incompleta hasta el punto de resultar engañosa."}]},{"t":"p","texto":[{"v":"Lo que hace la tokenización es "},{"v":"dividir","b":1},{"v":" un derecho en unidades pequeñas y hacerlas técnicamente transferibles. Eso elimina una barrera —la indivisibilidad— que efectivamente impedía la liquidez. Pero eliminar una barrera no equivale a crear un mercado."}]},{"t":"recuadro","tipo":"idea","titulo":"La idea central","bloques":[{"t":"p","texto":[{"v":"Un piso dividido en mil participaciones sigue siendo un piso que nadie ha comprado. La divisibilidad es una "},{"v":"condición necesaria","b":1},{"v":" de la liquidez. No es una condición suficiente, ni de lejos."}]}]},{"t":"h3","texto":[{"v":"Qué es liquidez de verdad: tres dimensiones, no una"}]},{"t":"p","texto":[{"v":"Cuando alguien dice «líquido», conviene desglosar la afirmación en tres preguntas independientes:"}]},{"t":"ol","items":[[{"v":"¿Puedo vender?","b":1},{"v":" ¿Existe alguna vía legal y operativa para transmitir mi participación a un tercero?"}],[{"v":"¿En cuánto tiempo?","b":1},{"v":" ¿Días, semanas, meses, o «cuando aparezca alguien»?"}],[{"v":"¿A qué precio?","b":1},{"v":" ¿Al valor razonable del activo, o con un descuento que refleja la urgencia de quien vende?"}]]},{"t":"recuadro","tipo":"aviso","titulo":"Aviso","bloques":[{"t":"p","texto":[{"v":"Si puedes vender, pero solo aceptando un descuento severo sobre el valor del activo, eso no es liquidez: es "},{"v":"una salida de emergencia","b":1},{"v":". La diferencia importa mucho, porque un inversor que compró creyendo lo primero y se encuentra lo segundo tiene una reclamación razonable — y va dirigida al emisor."}]}]},{"t":"h3","texto":[{"v":"Las cuatro condiciones que producen un mercado secundario"}]},{"t":"h4","texto":[{"v":"1 · Un lugar donde negociar que sea legal para ese instrumento"}]},{"t":"p","texto":[{"v":"Como viste en la Lección 4, los instrumentos financieros no se negocian en cualquier sitio. La negociación ocurre en infraestructuras autorizadas, y para las basadas en registro distribuido existe un régimen piloto europeo específico, con sus propias condiciones y límites."}]},{"t":"p","texto":[{"v":"Que un token sea técnicamente transferible entre dos carteras no significa que esa transmisión sea una operación de mercado válida para tu instrumento."}]},{"t":"h4","texto":[{"v":"2 · Profundidad: suficientes compradores y vendedores"}]},{"t":"p","texto":[{"v":"Un mercado con dos participantes no es un mercado. Hace falta una masa crítica de contrapartes potenciales interesadas en ese tipo de activo, en esa ubicación, con ese perfil de riesgo y ese horizonte. Es la condición más difícil de conseguir y la que menos se menciona."}]},{"t":"h4","texto":[{"v":"3 · Información fiable y periódica"}]},{"t":"p","texto":[{"v":"Nadie compra a ciegas. Para que un tercero se forme una opinión de precio necesita valoraciones actualizadas, información sobre la evolución del activo y datos comparables. Sin reporting periódico creíble, la única referencia de precio disponible es la del emisor, y eso ahuyenta al comprador informado."}]},{"t":"h4","texto":[{"v":"4 · Ausencia de fricciones en la transmisión"}]},{"t":"p","texto":[{"v":"Cada barrera reduce el universo de compradores: restricciones de transmisión en el documento de emisión, derechos de adquisición preferente, requisitos de identificación del comprador entrante, límites por tipo de inversor —minorista, cualificado— y el coste fiscal de la propia transmisión."}]},{"t":"h3","texto":[{"v":"Entonces, ¿qué aporta realmente la tecnología?"}]},{"t":"p","texto":[{"v":"Aporta algo real, y merece la pena decirlo con precisión porque es donde está el valor honesto de la propuesta:"}]},{"t":"ul","items":[[{"v":"Reduce el coste unitario de registrar una transmisión","b":1},{"v":", lo que hace viable un mercado de operaciones pequeñas que antes no compensaba administrar."}],[{"v":"Automatiza la liquidación","b":1},{"v":" y la actualización de la titularidad."}],[{"v":"Permite programar en el propio instrumento las reglas de transmisión","b":1},{"v":", lo que da control sobre quién puede entrar."}]]},{"t":"p","texto":[{"v":"Es decir: "},{"v":"la tecnología hace más barato y más rápido operar un mercado que ya existe. No lo crea.","b":1},{"v":" Cuando hay contrapartes, ayuda mucho. Cuando no las hay, no aporta nada."}]},{"t":"h3","texto":[{"v":"Los cuatro espejismos de liquidez"}]},{"t":"p","texto":[{"v":"Patrones que se presentan como liquidez y no lo son. Ninguno es necesariamente irregular; todos exigen preguntas concretas."}]},{"t":"p","texto":[{"v":"1 · El mercado interno de la propia plataforma.","b":1},{"br":1},{"v":"«Podrás vender tus participaciones a otros usuarios cuando quieras.»","i":1},{"v":" Podrás "},{"v":"ofrecerlas","b":1},{"v":". Que se vendan depende de que exista un usuario interesado en ese activo concreto en ese momento. La profundidad real está limitada a la base de usuarios de esa plataforma — pregunta cuántos son, cuántos operan y cuántas transmisiones se han cerrado realmente en los últimos doce meses. Y añade una pregunta incómoda: "},{"v":"si esta plataforma dejara de operar, ¿qué ocurre con el mercado?","i":1}]},{"t":"p","texto":[{"v":"2 · El compromiso de recompra del emisor o del promotor.","b":1},{"br":1},{"v":"Es una garantía de crédito, no liquidez. Su valor depende íntegramente de la solvencia de quien la ofrece "},{"v":"en el momento de ejecutarla","b":1},{"v":", que suele coincidir con el momento en que muchos quieren salir a la vez, es decir, cuando esa solvencia está más tensionada. Pregunta si el compromiso está garantizado, con qué, y quién responde si el obligado no puede."}]},{"t":"p","texto":[{"v":"3 · El creador de mercado contratado.","b":1},{"br":1},{"v":"Puede ser una solución seria. También puede ser un contrato que se cancela con un preaviso corto. Pregunta si existe obligación contractual de cotizar, con qué volumen mínimo, con qué diferencial máximo entre precio de compra y de venta, durante cuánto tiempo y en qué supuestos puede suspenderse."}]},{"t":"p","texto":[{"v":"4 · El volumen aparente en un mercado no regulado.","b":1},{"br":1},{"v":"Ver un token con movimiento en algún mercado abierto no dice nada sobre tu instrumento si ese entorno no es una vía válida de negociación para valores negociables, ni sobre si ese volumen corresponde a operaciones entre partes independientes."}]},{"t":"h3","texto":[{"v":"Las nueve preguntas antes de creer una promesa de liquidez"}]},{"t":"ol","items":[[{"v":"¿Dónde exactamente se podrá negociar esto, y esa infraestructura está autorizada para este tipo de instrumento?"}],[{"v":"¿Cuántas transmisiones reales entre inversores se han cerrado en esa vía en los últimos doce meses?"}],[{"v":"¿Cuál fue el plazo medio entre la puesta a la venta y la ejecución?"}],[{"v":"¿A qué precio se cerraron, comparado con la valoración vigente en ese momento?"}],[{"v":"¿Qué restricciones de transmisión incorpora el documento de emisión?"}],[{"v":"¿Qué requisitos debe cumplir el comprador entrante y cuánto tarda su alta?"}],[{"v":"Si existe compromiso de recompra o creador de mercado, ¿cuáles son sus obligaciones exactas y sus causas de suspensión?"}],[{"v":"¿Con qué periodicidad se publicará información y valoración actualizada del activo?"}],[{"v":"¿Qué ocurre con el mercado secundario si el proveedor cesa su actividad?"}]]},{"t":"p","texto":[{"v":"Un proveedor solvente responderá a la mayoría con datos. La incomodidad ante las preguntas 2, 3 y 4 es, por sí sola, una respuesta."}]},{"t":"h3","texto":[{"v":"Cómo presentar esto a tus inversores (y por qué te protege)"}]},{"t":"p","texto":[{"v":"Aquí la lección deja de hablarle al comprador y te habla a ti como emisor. Si tu material comercial promete una liquidez que después no existe, el problema no será comercial: será de "},{"v":"información al inversor","b":1},{"v":", y quien responde de la información que se entrega es el emisor."}]},{"t":"tabla","cabecera":[[{"v":"No escribas"}],[{"v":"Escribe"}]],"filas":[[[{"v":"«Inversión líquida» / «vende cuando quieras»"}],[{"v":"«Existe una vía de transmisión en [X]. No se garantiza que haya comprador ni a qué precio»"}]],[[{"v":"«Liquidez inmediata»"}],[{"v":"«Plazo de ejecución observado históricamente: [dato real, o indicar que no hay histórico]»"}]],[[{"v":"«Recompra garantizada»"}],[{"v":"«Compromiso de recompra a cargo de [entidad], sujeto a su solvencia y a las condiciones [X]»"}]],[[{"v":"«Mercado secundario activo»"}],[{"v":"«Número de transmisiones cerradas en los últimos 12 meses: [dato]»"}]]]},{"t":"recuadro","tipo":"idea","titulo":"La regla que resume esta lección","bloques":[{"t":"p","texto":[{"v":"Describe el "},{"v":"mecanismo","b":1},{"v":" disponible y los "},{"v":"datos","b":1},{"v":" observados. No prometas el "},{"v":"resultado","b":1},{"v":". Un inversor que entra sabiendo que el activo es ilíquido y decide entrar igualmente es un inversor tranquilo. Uno que descubre la iliquidez cuando quiere salir es una reclamación."}]}]},{"t":"h3","texto":[{"v":"Cuándo la iliquidez no es un problema"}]},{"t":"p","texto":[{"v":"Conviene cerrar sin dramatismo: "},{"v":"hay proyectos perfectamente sólidos que son ilíquidos por diseño, y no pasa nada","b":1},{"v":" — siempre que se presenten así."}]},{"t":"ul","items":[[{"v":"Deuda con calendario de amortización:","b":1},{"v":" el inversor no necesita vender, cobra en fechas conocidas."}],[{"v":"Activos con reparto periódico","b":1},{"v":" y horizonte de tenencia largo, donde el rendimiento viene del flujo y no de la reventa."}],[{"v":"Emisiones dirigidas a inversores cualificados","b":1},{"v":" que entran con horizonte definido y capacidad de análisis propia."}]]},{"t":"p","texto":[{"v":"La iliquidez solo se convierte en problema cuando se ha vendido lo contrario. Un proyecto honestamente ilíquido y bien remunerado es una propuesta perfectamente defendible; un proyecto ilíquido vendido como líquido es un pasivo."}]},{"t":"h3","texto":[{"v":"Qué viene ahora"}]},{"t":"p","texto":[{"v":"Has terminado el "},{"v":"Nivel Intermedio","b":1},{"v":". Sabes qué régimen te aplica, cuánto cuesta el proceso y qué esperar razonablemente de la liquidez."}]},{"t":"p","texto":[{"v":"El "},{"v":"Nivel Avanzado","b":1},{"v":" es el de la ejecución. En la "},{"v":"Lección 7","b":1},{"v":" aprenderás a leer el radar: cómo aplicar a tu caso concreto los cuatro criterios de verificación de RWAdar, qué comparar entre plataformas y cómo descartar candidatos por incompatibilidad objetiva antes de perder una sola reunión."}]}],"glosario":[{"termino":"Mercado secundario","definicion":[{"v":"Ámbito donde los inversores compran y venden entre sí instrumentos ya emitidos, sin que intervenga el emisor. Se distingue del mercado primario, que es la emisión inicial. Su existencia no es automática: requiere una vía de negociación válida, contrapartes e información."}]},{"termino":"Profundidad de mercado","definicion":[{"v":"Volumen de órdenes de compra y venta disponibles en un momento dado. Un mercado profundo absorbe operaciones sin que el precio se mueva bruscamente; uno superficial obliga a quien vende a aceptar descuentos crecientes a medida que aumenta el importe. Es la dimensión de la liquidez que más se omite en el material comercial."}]},{"termino":"Creador de mercado (market maker)","definicion":[{"v":"Participante que se compromete a ofrecer simultáneamente precios de compra y de venta, aportando contrapartida cuando no la hay entre inversores. Su utilidad depende por completo del contenido de su contrato: volumen comprometido, diferencial máximo entre ambos precios, duración y causas de suspensión."}]}],"quiz":[{"enunciado":[{"v":"Una plataforma afirma: «nuestro mercado interno te permite vender tus participaciones a otros usuarios en cualquier momento». ¿Qué describe realmente esa frase?"}],"opciones":[[{"v":"Una garantía de venta a valor razonable en cualquier momento"}],[{"v":"La posibilidad de "},{"v":"ofrecer","i":1},{"v":" tu participación; que se venda depende de que exista un comprador interesado dentro de la base de usuarios de esa plataforma"}],[{"v":"Liquidez equivalente a la de un mercado organizado"}],[{"v":"Una obligación de la plataforma de adquirir tu participación si nadie la compra"}]],"correcta":1,"explicacion":[{"t":"p","texto":[{"v":"Un tablón de anuncios interno permite publicar una oferta; no crea contrapartida. Su profundidad está limitada a los usuarios de esa plataforma concreta interesados en ese activo concreto en ese momento. Las preguntas que convierten la afirmación en información útil son cuantitativas: cuántas transmisiones se han cerrado realmente en los últimos doce meses, en qué plazo medio y a qué precio respecto de la valoración vigente. Y una cualitativa que casi nadie hace: qué ocurriría con ese mercado si la plataforma dejara de operar."}]}]},{"enunciado":[{"v":"El promotor de una emisión ofrece un compromiso de recompra de las participaciones al cabo de tres años. ¿Cómo debe interpretarse ese compromiso?"}],"opciones":[[{"v":"Como liquidez garantizada, ya que existe un comprador asegurado"}],[{"v":"Como una forma de mercado secundario organizado"}],[{"v":"Como una obligación de pago del promotor: su valor depende de su solvencia en el momento de ejecutarla, no de la existencia de un mercado"}],[{"v":"Como una garantía regulada equivalente a un depósito"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"Un compromiso de recompra traslada el análisis desde el activo hacia quien lo asume: es riesgo de crédito, no liquidez. Y tiene una característica que lo hace especialmente delicado: la probabilidad de que muchos inversores quieran ejercerlo a la vez aumenta justo cuando el proyecto atraviesa dificultades, es decir, cuando la capacidad de pago del promotor está más comprometida. Las preguntas pertinentes son si el compromiso está garantizado, con qué activos, y quién responde subsidiariamente si el obligado no puede atenderlo."}]}]},{"enunciado":[{"v":"De las cuatro condiciones que producen un mercado secundario —vía de negociación válida, profundidad, información periódica y ausencia de fricciones—, ¿cuántas aporta por sí misma la tecnología de registro distribuido?"}],"opciones":[[{"v":"Las cuatro: es precisamente su propuesta de valor"}],[{"v":"Dos: la vía de negociación y la ausencia de fricciones"}],[{"v":"Ninguna; lo que aporta es reducir el coste de registrar y liquidar las transmisiones cuando ya existen contrapartes"}],[{"v":"Solo la profundidad, al ampliar el acceso a inversores internacionales"}]],"correcta":2,"explicacion":[{"t":"p","texto":[{"v":"La tecnología no crea una vía de negociación legalmente válida —eso lo determina el régimen aplicable al instrumento—, no genera compradores, no produce información fiable sobre el activo y no elimina las restricciones de transmisión, que son jurídicas y contractuales. Lo que sí hace, y tiene valor real, es abaratar y acelerar el registro y la liquidación de las operaciones, haciendo viable administrar un mercado de importes pequeños. La opción D confunde alcance potencial con demanda efectiva: llegar a más inversores no equivale a que esos inversores quieran comprar."}]}]}],"siguientePaso":{"titulo":"Nivel Intermedio completado. Ahora contrasta lo que te cuentan.","bloques":[{"t":"p","texto":[{"v":"Ya tienes las nueve preguntas. Llévalas a cada conversación y compara las respuestas, no las presentaciones."}]},{"t":"p","texto":[{"v":"En el radar de RWAdar puedes filtrar por "},{"v":"nivel de acceso","b":1},{"v":" —minorista, acreditado, institucional, enterprise— y por región y tipo de activo, para ver a qué inversores llega realmente cada plataforma. Ese dato es el que más se aproxima a la profundidad potencial de su mercado."}]},{"t":"p","texto":[{"v":"Consulta también "},{"v":"Fuera del radar","b":1},{"v":": uno de nuestros cuatro criterios de verificación es la ausencia de crisis activas, y publicamos con motivo y fuente las plataformas que no lo superan."}]},{"t":"p","texto":[{"a":"radar-nivel-acceso","v":"Abrir el radar y filtrar por nivel de acceso"}]},{"t":"p","texto":[{"v":"¿Aún no has diagnosticado tu activo? El "},{"v":"Evaluador de Viabilidad","b":1},{"v":" te dice en qué punto estás y qué te falta. Puedes completarlo de forma anónima, sin identificar tu activo ni facilitar datos personales."}]},{"t":"p","texto":[{"a":"evaluador-viabilidad","v":"Probar el Evaluador de Viabilidad"}]}]},"notaLegal":[{"t":"p","texto":[{"v":"Sobre la liquidez.","b":1},{"v":" Las condiciones, espejismos y preguntas descritos en esta lección son un "},{"v":"marco educativo general","b":1},{"v":" para evaluar afirmaciones sobre liquidez, no una valoración de ninguna plataforma, producto o mecanismo concreto. Ninguno de los patrones descritos es irregular en sí mismo; su idoneidad depende de su configuración contractual específica. Las orientaciones sobre cómo describir la liquidez en materiales dirigidos a inversores son una advertencia general sobre buenas prácticas de información y "},{"v":"no sustituyen la revisión de dichos materiales por un profesional habilitado","b":1},{"v":", que en determinadas operaciones resulta legalmente exigible."}]}]},
  {"slug":"como-leer-el-radar","modulo":7,"titulo":"Cómo leer el radar: comparar proveedores sin dejarte deslumbrar","nivel":"avanzado","categoria":"Selección de proveedor","minutos":13,"resumen":"Un directorio te dice quién existe y quién ha superado un filtro. No te dice quién te conviene. Eso depende del encaje con tu caso, y ese análisis es tuyo.","publicado":false,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":true,"cta":"radar-comparador","url":"https://rwadar.pages.dev/academy/como-leer-el-radar"},
  {"slug":"expediente-de-tokenizacion","modulo":8,"titulo":"El expediente de tokenización: los doce documentos que te van a pedir","nivel":"avanzado","categoria":"Preparación","minutos":15,"resumen":"El expediente es la única palanca de coste y plazo que está enteramente en tus manos. Cada semana que dedicas a prepararlo es una semana que no pagas a tarifa profesional.","publicado":false,"revisionLegal":"2026-08-21","revisionLegalTexto":"21 de agosto de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":false,"cta":"evaluador-viabilidad","url":"https://rwadar.pages.dev/academy/expediente-de-tokenizacion"},
  {"slug":"despues-de-emitir-ciclo-de-vida","modulo":9,"titulo":"Después de emitir: gobierno, reporting, fiscalidad y ciclo de vida del token","nivel":"avanzado","categoria":"Post-emisión","minutos":17,"resumen":"Emitir es el principio, no el final. Una emisión viva genera obligaciones de gobierno, información, fiscalidad y mantenimiento que duran tanto como la emisión.","publicado":false,"revisionLegal":"2026-09-23","revisionLegalTexto":"23 de septiembre de 2026","jurisdiccion":"España / Unión Europea","avisoReforzado":true,"cta":"radar-comparador","url":"https://rwadar.pages.dev/academy/despues-de-emitir-ciclo-de-vida"},
];
